import fs from 'node:fs/promises';
import path from 'node:path';
import {out,tables,operations,buildContracts,openapi} from './contracts.mjs';
import {modules,workstreams,milestones} from './modules.mjs';
import {tokens,invariants,adrs,repoTree,comparisonChoices,contrastPairs,buildSupplements} from './supplements.mjs';

const e=x=>String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const link=(url,label)=>`<a href="${e(url)}">${e(label)}</a>`;
const cite=(url,label)=>` <span class="citation">${link(url,label)}</span>`;
const p=x=>`<p>${x}</p>`;
const list=items=>`<ul>${items.map(x=>`<li>${x}</li>`).join('')}</ul>`;
const table=(headers,rows,cls='')=>`<div class="table-wrap"><table class="${cls}"><thead><tr>${headers.map(x=>`<th>${e(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const code=x=>`<code>${e(x)}</code>`;
const callout=x=>`<aside class="callout">${x}</aside>`;
const reqs=m=>m.requirements.map((text,i)=>({id:`${m.id}-${String(i+1).padStart(3,'0')}`,text}));
const base='https://';

function svg(title,body,width=1120,height=500){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="${e(title)}"><title>${e(title)}</title><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L8,3 z" fill="#52617A"/></marker></defs><rect width="100%" height="100%" fill="#F5F7FB"/><style>text{font-family:Inter,Arial,sans-serif;fill:#172238}.heading{font-size:22px;font-weight:700}.label{font-size:17px;font-weight:700}.note{font-size:14px;fill:#52617A}.box{fill:white;stroke:#CBD3DF;stroke-width:1.5}.edge{stroke:#52617A;stroke-width:2;fill:none;marker-end:url(#arrow)}</style>${body}</svg>`;}
const box=(x,y,w,h,title,lines)=>`<rect class="box" x="${x}" y="${y}" width="${w}" height="${h}" rx="10"/><text class="label" x="${x+16}" y="${y+30}">${e(title)}</text>${lines.map((t,i)=>`<text class="note" x="${x+16}" y="${y+56+i*22}">${e(t)}</text>`).join('')}`;
const arrow=(x1,y1,x2,y2)=>`<path class="edge" d="M${x1},${y1} L${x2},${y2}"/>`;
