 'architecture.svg':svg('Proposed application and data architecture',`<text class="heading" x="28" y="36">Independent platform • proposed architecture</text>${box(28,70,270,120,'Next.js web / BFF',['Workspace + staff + public sites','OIDC session, verified site resolution'])}${box(380,70,350,120,'NestJS modular API',['SaaS · CRM · CMS · Marketing · IDX','Reports · AI · support · integrations'])}${box(812,70,280,120,'Isolated workers',['Outbox · delivery · MLS · publishing','Tenant context rechecked per job'])}${arrow(298,130,380,130)}${arrow(730,130,812,130)}${box(28,270,300,120,'PostgreSQL + PostGIS',['Canonical data, RLS, durable jobs','Composite tenant keys + transactions'])}${box(410,270,300,120,'Redis + private object storage',['Wakeups, scoped cache, rate limits','Scanned media; licensed derivatives'])}${box(792,270,300,120,'Provider adapters',['MLS modes · email · SMS · billing','OIDC · AI · maps · optional local'])}${arrow(550,190,178,270)}${arrow(590,190,560,270)}${arrow(950,190,945,270)}<text class="note" x="28" y="440">Managed deployment: OCI containers • secret manager • CDN • telemetry • backups • distinct migration/runtime identities</text>`),
