 'mls-pipeline.svg':svg('MLS adapter capability and licensing pipeline',`<text class="heading" x="28" y="36">MLS integration • policy governs every derived surface</text>${box(28,70,300,128,'M1 contract / M5 mock',['Owner-approved provider at M6','Discover capabilities + policy','Unknown rights → deny'])}${box(410,70,300,128,'Adapter transport',['Replication: durable change pages','Live query: bounded provider requests','Embed: licensed UI, no assumed storage'])}${box(792,70,300,128,'Normalize + validate',['Feed-scoped source keys / statuses','Field whitelist, attribution, expiry','Synthetic data rejected in live mode'])}${arrow(328,133,410,133)}${arrow(710,133,792,133)}${box(28,290,300,112,'Read/alert policy gate',['Current display + address + freshness','Licensed cache/media/alerts/AI use','Revocation blocks and invalidates'])}${box(410,290,300,112,'Serving surfaces',['Search · details · map · CMS blocks','Visitor organizer → CRM inquiry','Consent-aware listing alerts'])}${box(792,290,300,112,'Sync + reconciliation',['Upsert / delete → committed page','Advance opaque checkpoint last','Retry, dedupe, monitor, reconcile'])}${arrow(945,198,945,290)}<path class="edge" d="M945,402 V438 H178 V402"/>${arrow(328,365,410,365)}<text class="note" x="28" y="455">No live feed, proprietary data, provider assumptions or credentials are included in this blueprint.</text>`,1120,500),
