const stackRows=[
 ['Runtime / repository','Node.js 24 LTS; TypeScript strict; pnpm workspaces','Pin secure compatible patch versions and a lockfile at M1. Choose Next.js 16 supported family and its declared React peer version; do not independently force mismatched React. Node 24 is an LTS line, not a recommendation to float “latest”.'+cite('https://nodejs.org/en/about/previous-releases','Node release schedule')],
 ['Frontend','Next.js App Router; server-rendered public sites; scoped BFF','Server components for layouts/data; client islands for maps, builders and workspace interactivity. Keep credentials and provider calls server-side; verify both BFF and API guards.'+cite('https://nextjs.org/docs/app/getting-started/server-and-client-components','Next.js server/client boundaries')],
 ['UI / state','Tailwind CSS 4; Radix primitives; TanStack Table/Query; Lucide','Shared tokens/components. Query cache keys include tenant, scope, resource and version. URL owns filter state; local React owns transient UI. No initial Redux store. React Hook Form with shared JSON Schema/Ajv validation.'+cite('https://tailwindcss.com/docs/theme','Tailwind theme variables')],
 ['Backend / API','NestJS modular monolith; REST; OpenAPI 3.1.1','Domain modules own repositories and policies; guards run before business commands. Generate typed clients from the committed API, with CI drift checks.'+cite('https://docs.nestjs.com/openapi/introduction','Nest OpenAPI')],
 ['Database / migrations','Managed PostgreSQL 17 + PostGIS; Drizzle + node-postgres','SQL is explicit and reviewed; ORM does not replace RLS. Compatible supported versions are pinned after M1 migration tests. Do not call the provided baseline a validated migration.'+cite('https://orm.drizzle.team/docs/rqb','Drizzle query documentation')],
 ['Jobs / cache','BullMQ + Redis, PostgreSQL outbox/jobs','Bounded concurrency, persistent Redis with noeviction and private TLS; Redis wakes durable database work. Tenant-local idempotency and job leases survive queue redelivery.'+cite('https://docs.bullmq.io/guide/going-to-production','BullMQ production guidance')],
 ['CMS / email editor','Puck adapter; versioned native blocks; Unlayer adapter','Puck keeps the platform’s content data and rendering. Email editor licensing and export support need procurement; editable email JSON and sanitized rendered output are stored together.'+cite('https://puckeditor.com/docs','Puck documentation')+cite('https://docs.unlayer.com/builder/email-builder','Unlayer email builder')],
 ['Authentication / billing','Entra External ID OIDC; Stripe','Use a new customer identity service rather than assume access to a legacy B2C purchase. Hosted identity does not supply organization authorization. Merchant configuration and taxes require M2 setup.'+cite('https://learn.microsoft.com/en-us/entra/external-id/customers/overview-customers-ciam','External ID customer overview')],
 ['Communication','Resend email; Twilio SMS; provider ports','Proposed providers, not audited Agent Elite transport claims. Sandbox/no-delivery before launch; verify domain, SMS readiness, receipts, signatures and quota capabilities.'+cite('https://resend.com/docs/api-reference/introduction','Resend API')+cite('https://www.twilio.com/docs/messaging/guides/webhook-request','Twilio webhook requests')],
 ['Maps / search','PostGIS + PostgreSQL text; MapLibre + licensed tiles/geocoding','Use a MapTiler or equivalent adapter after procurement. No production dependence on demo/public tiles. List views remain available without maps; bound bbox and query cost.'+cite('https://postgis.net/docs/ST_DWithin.html','PostGIS distance query')],
 ['AI / observability','OpenAI Responses API; OpenTelemetry; managed metrics/logs','Model and prompt choices follow evaluations. Correlation and safe error codes, no raw message bodies or credentials in telemetry. Provider outage degrades draft assistance without blocking CRM.'+cite('https://developers.openai.com/api/docs/guides/structured-outputs?api-mode=responses','OpenAI structured outputs')],
 ['Infrastructure','Azure Container Apps; PostgreSQL; Blob; Key Vault; CDN; Terraform','Separate web/API/worker scaling and migration job. Private database/cache, managed identities, independently scoped storage and secret references. Optional Sentry requires approved redaction/region; no Kubernetes initially.']
];

function moduleHtml(m){const ops=operations.filter(o=>o.module===m.code);return `<article class="module" id="${m.id}"><h3>${m.id} · ${e(m.name)}</h3><p class="meta">${e(m.milestone)} · Owner: ${e(m.owner)}</p>${p(e(m.purpose))}<h4>Functional requirements</h4><ol class="requirements">${reqs(m).map(r=>`<li id="${r.id}"><strong>${r.id}</strong> ${e(r.text)}</li>`).join('')}</ol>${table(['Specification','Decision'],[['Dependencies',e(m.dependencies)],['Entities',code(m.entities)],['Permissions and scope',e(m.permissions)],['UI components',e(m.ui)],['External integrations',e(m.integrations)],['API contract',ops.length?ops.map(o=>link('#api-'+o.id,o.id)).join(' · '):'Shared integration contract; see API appendix.']])}<h4>Acceptance criteria</h4><ol>${m.acceptance.map((x,i)=>`<li id="${m.id}-AC-${i+1}"><strong>${m.id}-AC-${i+1}</strong> ${e(x)}</li>`).join('')}</ol>${p('<strong>Verification:</strong> '+e(m.tests))}</article>`;}

export async function buildDocument(audit){
 const contractStats=await buildContracts();const supplementStats=await buildSupplements(audit);await fs.mkdir(path.join(out,'diagrams'),{recursive:true});for(const [name,body]of Object.entries(diagrams))await fs.writeFile(path.join(out,'diagrams',name),body);
 if(audit.inventory.length!==comparisonChoices.length)throw new Error('Feature comparison count mismatch');
 const comparison=audit.inventory.map((row,i)=>({id:`AE-${String(i+1).padStart(3,'0')}`,category:row[0],feature:row[1],route:row[2],observed:row[3],auditDepth:row[6],evidence:row[7],classification:comparisonChoices[i][0],module:comparisonChoices[i][1],milestone:comparisonChoices[i][2],proposal:comparisonChoices[i][3]}));
 const sections=[];const section=(id,title,html)=>sections.push({id,title,html});
 section('overview','1. Delivery, scope and decision status',
 callout('<strong>This is a development blueprint, not an implemented application.</strong> All new behavior, schemas, APIs, fixtures, diagrams and performance targets are proposed. The SQL has not been executed against PostgreSQL; provider contracts, costs and production readiness remain milestone gates.')+
 p('Build an independent platform around one verified organization context, a native CRM, versioned websites and marketing, and a property layer that honors the eventual Las Vegas provider’s capabilities. Prioritize complete daily workflows and dependable outcomes over recreating every reference product.')+
 table(['Design baseline','Scope'],[['Version / date','TDD 1.0 · 10 October 2026 · Asia/Bangkok'],['Evidence input',link('reference/source-audit.json','Entire prior audit, structured source')+' · '+link('reference/Agent-Elite-Audit-2026-10-10.zip','Original audit and retained evidence bundle')],['Core launch','M1–M5 foundation, SaaS/CRM, CMS, marketing, full mobile/PWA workflows and clearly synthetic IDX; live Las Vegas IDX needs M6 approval.'],['Competitive enhancements','M7 assistive AI, defined reporting and optional local visibility; advanced design/print studio, rank tracking and mortgage calculators deferred.'],['Practical artifacts',`${tables.length} table definitions; ${operations.length} API operations; ${modules.length} modules; ${workstreams.length} workstreams; ${milestones.length} milestone gates; ${comparison.length} audit-feature mappings.`],['Terminology','Organization = tenant; member = identity’s organization membership; visitor = site-bound public organizer identity; platform staff = separate control plane.'],['Independent design','Original navigation, tokens, content models and code. No copied Agent Elite source, proprietary templates or restricted MLS records.']])+
 p('Commercial decisions still open: brand, exact plans/limits, hosting region, traffic forecast, provider procurement, retention obligations and launch scope. Proposed defaults make implementation concrete; owners approve these at the relevant gate. Do not delay M1 on live MLS credentials or presume that every listed connector is required.')+
 `<h3>Non-negotiable implementation invariants</h3>`+table(['ID','Boundary','Required behavior'],invariants.map(r=>r.map(e))));

 section('audit','2. Audit translation and feature comparison',
 p('The source audit reviewed authenticated portal, white-label CRM/IDX, WordPress and public website surfaces. It retained 72 feature observations, 30 technology findings, 28 integration entries, 15 workflows and 14 gaps. UI or source evidence demonstrates a surface; it does not prove writes, business enforcement, message delivery, feed licensing or production latency. No audit finding establishes the actual database engine.')+
 table(['Reference layer','Evidence label','Architecture implication'],[
 ['Portal','Confirmed: Bootstrap/jQuery assets, Kestrel response marker and Azure AD B2C flow. Inferred: .NET/Razor-family rendering; backend internals unknown.','Replace product launches and duplicate identity boundaries with one native workspace.'],
 ['CRM / IDX','Confirmed: iHomefinder/IDXHome surfaces, React 17 bundle and cross-origin control-panel API. Bundled libraries do not establish every active integration.','Native tenant-scoped CRM; replace remote account handoff. Property data access remains provider-dependent.'],
 ['Website editing','Confirmed: WordPress 6.8.5, Genesis-family Monterey/Awesomeberg, Gutenberg, Gravity Forms and Yoast assets. Origin hosting/database unproven.','Independent blocks/templates, stable revision model, clearer errors and one publishing workflow.'],
 ['Communication / billing','Confirmed: Unlayer designer and Stripe handoff/receipt surface. Actual email/SMS transport and exact payment implementation unknown.','License an editor if justified; own orchestration and use separately verified delivery/payment adapters.'],
 ['Local visibility / Design Studio','Yext-backed portal API observed. Advanced destination inspection blocked; premium design editor features documented only.','Do not invent advanced runtime behavior. Defer unclear products; distinguish coverage proxies from measured AI-answer visibility.'],
 ['UX / performance','Audit found ambiguous metric denominators, pricing presentation, editor warnings and a small blue CTA contrast ratio 2.753:1. Uncompressed bundle size was observed, not a latency benchmark.','Defined metrics and costs, accessible shared components, lazy editors/maps and measured budgets.']])+
 p('“Match” preserves useful behavior. “Improve” strengthens a verified surface. “Redesign” changes the model or workflow. “Defer” keeps an option outside launch. “Remove” excludes a proposed equivalent of an unsubstantiated metric. Each row preserves its inspection limitation; a documented or gated feature is not promoted to verified runtime behavior.')+
 `<label class="filter-label" for="feature-filter">Filter feature comparison <input id="feature-filter" type="search" placeholder="Feature, module, milestone or decision" autocomplete="off"/></label><p id="filter-count" role="status">72 audit features</p>`+
 table(['Trace / feature','Audit evidence and depth','Decision / proposed behavior','Owner / gate'],comparison.map(x=>[`<strong>${x.id}</strong><br>${e(x.category)} · ${e(x.feature)}<br><small>${e(x.route)}</small>`,`${e(x.observed)}<br><em>${e(x.auditDepth)}</em><br><small>Evidence inside audit ZIP: ${e(x.evidence)}</small>`,`<span class="badge">${e(x.classification)}</span> ${e(x.proposal)}`,`${link('#'+x.module,x.module)}<br>${e(x.milestone)}`]),'feature-matrix')+
 `<h3>New competitive capabilities</h3>`+table(['Proposed addition','Purpose','Requirement / gate'],[
 ['Unified tenant and permission model','Prevent fragmented users and accidental cross-product access.','MOD-A-002/003 · M1–M2'],['Immutable publish and campaign versions','Recover edits and make active automation reproducible.','MOD-C-003; MOD-E-002 · M3–M4'],['Durable visible jobs','Expose pending/failed work instead of optimistic success.','INV-03/09 · M1 onward'],['Native contact/lead/deal separation','Preserve people while managing multiple inquiries and deals.','MOD-D-001 · M2'],['Consent evidence and send-time checks','Prevent campaign eligibility from becoming stale.','MOD-E-004/005 · M4'],['Capability-aware IDX','Work with authorized replication, query or embed providers.','MOD-F-001/002 · M1/M5/M6'],['Current rights and freshness gates','Stop withdrawn or unlicensed data on every surface.','MOD-F-003/004 · M5/M6'],['Transparent metric definitions','Make reports interpretable and reconcile their counts.','MOD-G-001/002 · M2/M7'],['Reviewed AI drafts with citations','Reduce authoring effort while keeping factual and human control.','MOD-H-001/003 · M7'],['Previewed financial changes','Make plan/cancellation impact explicit before confirmation.','MOD-A-004/005 · M2'],['Import review and formula-safe exports','Reduce data loss and spreadsheet injection.','MOD-D-006 · M2'],['Time-bound staff grants','Support customer issues with traceable restricted access.','MOD-A-006 · M2']]));

 section('architecture','3. Platform architecture and stack',
 `<figure><img src="diagrams/architecture.svg" alt="Proposed architecture linking Next.js, NestJS, workers, PostgreSQL, Redis, storage and provider adapters"/><figcaption>Proposed architecture. The reference platform’s hosting is not the deployment specification.</figcaption></figure>`+
 table(['Area','Selected baseline','Reason / tradeoff'],stackRows)+
 p('Deploy one web image, one API image and one worker image from the same revision. The workspace and public renderer may be split into separate deployments later if cache policy or load requires it; they share block and contract packages now. API commands perform authorization and domain validation before a short database transaction. Provider calls use timeouts and bounded retries outside that transaction. Publishing and delivery complete through durable jobs.')+
 p('Keep domain modules internally layered: controller → validated command/query → policy → service → repository. Service ports return domain DTOs, never raw ORM models. Jobs contain identifiers and expected versions rather than serialized customer records or tokens. Never make a public SSR handler depend on a tenant-wide CRM query.')+
 `<h3>Architectural decisions</h3>`+table(['ADR','Decision','Rationale'],adrs.map(r=>r.map(e)))+
 `<h3>Cache and query strategy</h3>`+list([
 'Public content cache key: verified site/domain + published revision + locale + template/block version. Invalidate after the publish transaction and retain a bounded stale-on-error policy only for approved public content.',
 'Property cache key: tenant/site + feed + filter hash + provider mapping + policy version. TTL cannot exceed provider rights or source freshness. Recheck listing availability and attribution before returning cached/indexed IDs. Rights revocation cannot wait for ordinary TTL expiry.',
 'Workspace server/client caches include active tenant and permission scope. Organization switching clears previous sensitive query data immediately and cancels in-flight requests. A scope change increments authorization cache generation.',
 'Use cursor indexes for CRM and listings; reject pathological wildcards, unsupported filters, unbounded geographic extents and excessive query costs. Begin with PostgreSQL plans on synthetic scale datasets; external search is an explicit later ADR.'
 ]));

 section('modules','4. Module specifications and acceptance criteria',
 p('These numbered requirements are the implementation contract. Each module identifies the shared services it needs, owned entities, API operations, UI and testable outcomes. Cross-module commands and event payloads use the shared contracts; module names do not imply separate microservices.')+modules.map(moduleHtml).join(''));

 section('security','5. Identity, tenancy, permissions and staff administration',
 p('OIDC flow: BFF generates state, nonce and PKCE challenge; callback verifies issuer, audience, signature, state, nonce and token lifetime. Link identities by verified issuer + subject, not an email string alone. Store an opaque rotating session server-side and set a Secure, HttpOnly, SameSite cookie. Require fresh authentication for billing, staff grants and high-impact role changes. Preserve browser password managers and paste.')+
 p('Every organization API checks active membership, current tenant status, permission code, entitlement and row scope. RLS enforces tenant separation; own/team/organization is an additional query policy, never a post-filter applied after returning counts. Teams initially mean offices with explicit active office membership. A read-only aggregate cannot disclose records that individual reads forbid.')+
 table(['Preset','Allowed scope / responsibilities','Restrictions'],[
 ['Owner','Organization configuration, members, roles, content, CRM, marketing, reports, billing and integrations.','Must preserve final active owner; no platform staff permissions. Sensitive export/send/publish actions remain explicit permissions and audit events.'],
 ['Organization manager','Organization CRM, office/team membership, pipeline/routing, tasks and reports.','No billing, staff grant or owner-role delegation by default. Publishing/sending can be assigned explicitly.'],
 ['Agent','Own contacts/leads/deals/tasks; own dashboard/notifications; approved site/property read access.','No organization-wide CRM export, member/routing configuration or sending to another owner’s contacts. Team scope requires an approved office role.'],
 ['Marketing editor','Organization content/message draft editing, media and campaign design.','Publish/send are separate grants; no financial or unrestricted CRM write permissions. Audience preview is constrained by approved recipient scope.'],
 ['Billing administrator','Billing read/manage and invoice access.','No default CRM/contact/content permissions.'],
 ['Read-only analyst','Approved own/team/organization reporting and relevant read projections.','No edits, sends, publishes, data exports or raw contact/message access unless separately granted.'],
 ['Platform staff','Control-plane organization health and operational statistics.','Tenant access requires approved time-bound purpose/permission grant. Grant creator cannot self-approve unrestricted customer access; step-up and separate approval policy required.'],
 ['Visitor','Own saved searches/favorites under a verified published site.','No organization APIs or cross-site organizer records. Passwordless login challenges are hashed, short-lived, one-use and rate-limited; identical response prevents email enumeration.']])+
 p('Release feature flags live in reviewed deployment configuration; staff can read active configuration and health, while plan metadata changes use explicit audited platform endpoints. The complete permission-code list is '+link('contracts/permission-catalog.json','permission-catalog.json')+' and '+link('contracts/role-presets.json','role-presets.json')+'. A code is an operation capability, not sufficient row authorization. The companion built-in role preset file defines explicit code/scope grants; M1 implements and tests them as fixtures. Custom role delegation is the intersection of delegatable codes and the caller’s scope; owner and platform escalation are dedicated guarded commands.')+
 p('The server opens a transaction and applies transaction-local app.tenant_id, app.actor_id and verified issuer/subject through parameterized set_config calls. Never set persistent pool session context. After commit/rollback the next borrower must see no previous context. Missing context denies rows. Identity bootstrap needs the verified issuer/subject path before the local actor exists; organization provisioning uses a separately reviewed control-plane role, not the ordinary runtime role.')+
 p('FORCE ROW LEVEL SECURITY does not constrain superusers or BYPASSRLS roles. Runtime and worker identities must therefore be non-owner, NOSUPERUSER and NOBYPASSRLS; the migration identity is separate. The supplied SQL revokes PUBLIC and defines policies, but intentionally leaves reviewed role/grant provisioning to M1. Use column/table privileges for immutable audit, consent and history evidence; administrative deletion/retention uses a restricted audited worker.'+cite('https://www.postgresql.org/docs/17/ddl-rowsecurity.html','PostgreSQL row security'))+
 p('Public requests resolve an exact approved domain to a published site and tenant; a site ID alone is not enough. Reject unknown hosts and untrusted forwarded headers. The public runtime receives only approved read projections plus narrowly scoped form/inquiry commands; it cannot query unrestricted CRM tables. Custom-domain visitor sessions are site-bound and separate from workspace cookies. CSRF/Origin checks apply to cookie-authenticated visitor mutations as well as workspace mutations. Anonymous form anti-abuse uses rate limits, honeypot and optional accessible challenge with server validation.'));

 section('data','6. Data model, relationships, indexing and migrations',
 `<figure><img src="diagrams/domain-relationships.svg" alt="Grouped proposed entity relationships across identity, CRM, CMS, marketing, property and execution"/><figcaption>Grouped map for reading. Full field-level ER source: ${link('data/schema.mmd','schema.mmd')}.</figcaption></figure>`+
 p('Canonical schema: '+link('data/schema.sql','schema.sql')+'; structured metadata: '+link('data/data-dictionary.json','data-dictionary.json')+'. There are 72 proposed tables. Business tables use (tenant_id, id) composite primary keys and tenant-scoped foreign keys, preserving isolation even when a caller guesses a valid ID from another organization. Global records are organization, user identity, platform staff and public plan catalog; their access policies differ explicitly.')+
 table(['Model rule','Required implementation behavior'],[
 ['Identity / membership','user_identity is globally issuer/subject unique; membership binds identity, organization, role, status and offices. Avoid merging identities by unverified email.'],
 ['Contact / lead / deal','Contact owns channels; a lead tracks intent/source/stage/assignment and a deal tracks commercial progress. Contact archival cascades domain cancellation through commands/events, not a blind destructive SQL cascade.'],
 ['Published revision pointer','content_document.published_revision_id references a revision of the SAME document using a composite FK. Content edits append immutable revisions; publishing/rollback atomically swaps the pointer after version checks.'],
 ['Campaign versions','An enrollment references a published campaign version; editing a draft does not rewrite current scheduled actions. Freeze each message snapshot (rendered template, design version/hash and merge-field schema) at campaign publication and copy it into scheduled actions. Workers use this snapshot rather than a mutable message_design row; generation and step references bind actions to cancellation/version checks.'],
 ['Listing identity','(tenant_id, feed_id, source_listing_key) is stable/unique. Public listing ID is platform-owned; source IDs can collide across feeds. Preserve source status and mapping version; unknown status is non-displayed unless explicitly approved.'],
 ['Domain ownership','Normalized lower-case hostname has global uniqueness. Domain takeover/reassignment needs verified ownership, detach/release audit and CDN/TLS reconciliation; tenant uniqueness alone is insufficient.'],
 ['Audit / events / jobs','Events and jobs retain references, state, correlation, attempts and safe error codes. Immutability is enforced by grants and approved service methods, not merely by describing a table as an audit log.'],
 ['JSONB','Use for versioned block data, safe configuration, attribution and policy structures validated against schemas. Do not use unrestricted JSONB as an excuse to accept arbitrary fields or secret payloads.'],
 ['Versions / timestamps','Every business mutation increments row_version and updated_at in the service transaction. The baseline has defaults, not automatic update triggers. Use UTC instants and IANA timezone IDs; monetary currency/amount semantics are explicit per API field.']])+
 `<h3>Indexes and query safeguards</h3>`+list([
 'Tenant-first B-tree indexes support foreign keys and cursor pagination. CRM uses created_at/id and owner/stage partial indexes for active leads; task due indexes target open assigned tasks. Contact channels use normalized kind/value lookup without implying cross-tenant deduplication.',
 'Property search uses tenant/feed/status/price indexes, PostGIS GIST geography and a GIN public-remarks text expression. Combine tenant and policy predicates in every plan; a spatial index alone is not a tenant security mechanism. Radius queries use meters; limit bbox area/results and validate longitude/latitude ordering.',
 'Queue dispatch indexes cover pending due actions and unpublished outbox rows. A scheduler enumerates approved organizations through the control plane, then enters each tenant context; the index does not authorize a cross-tenant bypass scan.',
 'Measure plans and index write overhead before adding broad JSON indexes. Reporting builds tenant/day aggregates; high-volume activity may be time-partitioned after measured growth. Do not partition all 72 tables in the first migration.'
 ])+
 `<h3>Migration sequence</h3>`+p('M1 splits the baseline into reviewed migrations: extensions/schema and functions → global tables → tenant tables/constraints → indexes → policies → runtime/control-plane roles and grants → deterministic role/pipeline fixtures. Test an empty database, a prior-version database, upgrade rollback at the application level and pool reuse under actual roles. CI owns a migration registry and rejects duplicate identifiers.')+
 p('Use expand → compatible application → batched tenant-aware backfill → validation → contract. Online index creation is a separate nontransactional migration where necessary. Keep the last application release compatible while jobs drain. Roll back application code against compatible schema; destructive rollback is not the default recovery plan. Long backfills checkpoint per tenant and throttle against production load.')+
 `<h3>Retention proposal — policy decisions, not legal conclusions</h3>`+table(['Record class','Initial design default','Gate / deletion behavior'],[
 ['CRM / deals / notes','While active subscription and owner-approved business retention apply; no universal automatic duration.','M2 establishes owner/jurisdiction policy. Deletion anonymizes eligible contact channels/notes while preserving required minimal evidence. Legal holds override ordinary schedules.'],
 ['Raw public analytics','30 days raw safe event metadata; 13 months nonidentifying aggregates.','M7 approves cookies/consent, region and identifiers. Do not store full URLs containing contact data or raw form bodies.'],
 ['Job / webhook diagnostics','30 days redacted payload references; 90 days operational state.','M1/M4 adjusts to provider replay windows. Long-term audit keeps safe metadata rather than raw payloads.'],
 ['Security / billing / consent audit','Proposed 24 months minimum safe audit, with separately approved billing/consent evidence schedules.','Owner/compliance review at M2/M4; no claim this meets all legal obligations. Role permissions limit erasure.'],
 ['MLS / media / caches','Exactly the approved feed policy; unknown duration means unresolved and live enablement blocked.','M6 enforces withdrawal, expiration and termination purge across objects/index/cache/AI retrieval.'],
 ['Exports / uploads','Signed downloads 5 minutes; completed export objects 24 hours; abandoned upload grants 1 hour.','Download rechecks current membership; object lifecycle deletes expired temporary data.'],
 ['AI inputs/results','Keep scoped references and approved drafts; transient unaccepted results proposed 7 days.','M7 reviews provider data agreement and purpose retention. store:false does not establish zero provider retention.'],
 ['Backups','Proposed 30-day PITR/backup window in approved region.','M8 verifies restore and deletion/retention treatment of backups; expired data must not silently return to service on restore.']])+
 `<h3>Field-level entity dictionary</h3><p>Expand any entity below. Constraints and foreign relationships are design definitions; SQL execution remains an M1 acceptance gate.</p>`+tables.map(t=>`<details id="entity-${t.name}"><summary>${e(t.name)} <span class="meta">${t.global?'global / special policy':'tenant composite key'} · ${t.columns.length} fields</span></summary>${table(['Column','SQL type','Constraint/default'],t.columns.map(c=>[code(c.name),code(c.type),code(c.rule)]))}${p('<strong>Relationships:</strong> '+(t.foreign.length?t.foreign.map(f=>`${code(f.column)} → ${link('#entity-'+f.target,f.target)}.${code(f.targetColumn)}`).join('; '):'No module FK beyond tenant ownership.'))}${p('<strong>Unique keys:</strong> '+e(JSON.stringify(t.unique)))}</details>`).join(''));

 section('api','7. API conventions, validation and operation contracts',
 p('Normative machine-readable baseline: '+link('contracts/openapi.json','OpenAPI 3.1.1 contract')+'. The reserved .example host is not a deployed endpoint. All operations declare schemas, security, permission metadata, tenant context, rate policy and standard error responses. The artifact is structurally checked; framework generation and full request conformance require implementation tests.'+cite('https://spec.openapis.org/oas/v3.1.1.html','OpenAPI 3.1.1'))+
 table(['Convention','Contract'],[
 ['Version / transport','HTTPS JSON under /v1. Additive optional fields within v1; breaking field meaning, required input or authorization behavior needs reviewed version/deprecation plan. Public site APIs and staff APIs remain separate namespaces.'],
 ['Schema validation','Reject unknown command properties, oversized strings/arrays, malformed UUIDs/dates and invalid enum values. Validate dynamic block/provider config against its versioned allowlist. Normalize phone/email cautiously; never convert missing consent to permission.'],
 ['Business validation','Check priceMin ≤ priceMax, valid bbox [west,south,east,north], geographic extent, supported filters and IANA timezone. Referenced owner/contact/site/lead/campaign/feed IDs must belong to the verified tenant and be in allowed scope.'],
 ['Pagination','Opaque signed cursor; stable sort plus ID tie-breaker, default 25, maximum 100. Cursor binds tenant, actor scope, filter/sort hash and expiry. Changed filters invalidate the cursor. Do not expose raw SQL offsets for large feeds.'],
 ['Filtering','CRM page filter is the LeadFilter contract; endpoints reject fields that lack semantics for that resource. Listing filter is JSON-encoded ListingCriteria; unsupported capabilities return 422 with field details rather than being ignored.'],
 ['Mutations / concurrency','Idempotency-Key on state-changing commands. PATCH/PUT require If-Match; publish commands include expected document/version IDs. Return 412 for stale versions; preserve editor work for manual conflict resolution.'],
 ['Idempotency','Store tenant + actor + route + key + canonical request hash and outcome. Same key/same hash replays outcome; same key/different hash returns 409. Retain key records at least 24 hours and longer for durable provider side effects until reconciliation is complete. Provider dedupe windows are separately discovered.'],
 ['Session / CSRF','Verified BFF cookie, current active membership and row policy; X-CSRF-Token plus exact Origin for workspace writes. Site-bound visitor cookie writes require equivalent CSRF protection. Public webhook authentication is provider signature verification, never a workspace cookie.'],
 ['Asynchronous commands','202 returns durable job reference and state; polling getJob returns pending/running/succeeded/failed with safe error/retry information. Enforce job ownership/module scope. A successful enqueue is not evidence of a successful provider operation.'],
 ['Errors','application/problem+json follows RFC 9457 with type/title/status/code/detail/traceId and safe validation fields. No SQL, raw provider errors, secret URLs or other tenant existence details.'+cite('https://www.rfc-editor.org/rfc/rfc9457.html','RFC 9457')],
 ['Planning rate defaults','300 read and 120 write requests/member/minute; AI 20 jobs/member/hour plus organization cost cap; public forms 10/IP/site/10 minutes. These are configurable product defaults, not vendor quota claims. Also limit body sizes, global concurrency and tenant storage/send volume.'],
 ['Quota feedback','429 includes Retry-After and trace ID; scoped counters do not reveal other tenants’ quotas. Third-party rate failures use bounded delayed jobs and visible degraded state.'],
 ['Webhooks','Route provider/connection identifies an existing approved connection; exact provider payload is verified before internal normalization. Transactionally store inbox event and deduplication record before 200 acknowledgment. Reject invalid/replayed signatures and never trust payload tenant IDs.']])+
 p('Stripe uses Stripe-Signature, Twilio uses X-Twilio-Signature, and Resend uses the Svix header set. The route selects only that provider’s verifier. Capture raw bytes before JSON parsing where required; use configured canonical public URLs for signatures, timestamp tolerances, secret rotation and provider event-ID deduplication. A valid signature from another provider never authorizes this route.'+cite('https://docs.stripe.com/webhooks','Stripe webhook verification')+cite('https://resend.com/docs/webhooks/introduction','Resend webhooks'))+
 `<h3>Command example: capture, route and return a durable receipt</h3><pre>${e(JSON.stringify({method:'POST',path:'/v1/public/sites/{siteId}/form-submissions',headers:{'Idempotency-Key':'fixture-submission-0001'},body:{formId:'00000000-0000-4000-8000-000000000001',formVersion:1,values:{name:'Sample Contact',email:'sample@example.invalid',email_marketing:false,sms_marketing:false}},note:'Values must match the published form schema, including explicit consent fields. Attribution comes from validated server-side site/session context. No real contact or consent claim.'},null,2))}</pre>`+
 `<h3>Operation index</h3><p>Input/output names link logically to OpenAPI components. All schemas and required fields are in the contract file; shared semantic requirements above remain mandatory. Each operation includes standard 400/401/403/404/409/412/422/429/503 errors as applicable.</p>`+
 [...new Set(operations.map(o=>o.module))].map(name=>`<details open><summary>${e(name)} · ${operations.filter(o=>o.module===name).length} operations</summary>${table(['Operation / method / endpoint','Input → output','Guard / permission'],operations.filter(o=>o.module===name).map(o=>[`<span id="api-${o.id}"><strong>${e(o.id)}</strong></span><br>${code(o.method.toUpperCase())} ${code(o.url)}`,`${o.webhook?'Exact vendor payload (not internal WebhookEnvelope)':o.input?code(o.input):'No body'} → ${code(o.page?'Page'+o.output:o.output)}${o.output==='Job'?'<br>202 durable job':''}`,`${code(o.permission)}<br>${o.staff?'Staff control plane':o.unsubscribe?'Signed channel/purpose token':o.visitor?'Site + own visitor':o.public?'Verified published site':o.webhook?'Exact provider signature':'Active member + tenant/row scope'}`]))}</details>`).join(''));

 section('execution','8. Events, durable jobs and orchestration',
 p('Commit the domain mutation and outbox event together. The dispatcher publishes the same eventId until acknowledged; consumers maintain a tenant/event/consumer dedupe ledger in the durable job/inbox records. Use at-least-once transport and idempotent effects, without claiming universal exactly-once message delivery. Correlation IDs link the browser command, transaction, job and provider reference.')+
 p('The '+link('contracts/events.schema.json','event-envelope schema')+' defines tenant, event ID/type/version, aggregate, occurrence/ingestion times, causation and a small reference-only payload. Each listed type uses the same payload shape: resourceId is the aggregate record; resourceVersion is its committed version; relatedResourceIds are scoped references, not customer data. Consumers reload data under current authorization before acting.')+
 table(['Event type','Producer / aggregate','Consumers / effect'],[
 ['lead.captured','CRM / lead','Routing, dashboard and marketing trigger evaluation.'],['lead.assigned','CRM / lead','Owner notification and scoped metrics.'],['lead.stage_changed','CRM / lead','Versioned automation eligibility and pipeline aggregates.'],['contact.archived','CRM / contact','Cancel future enrollments; suppress eligible alerts and remove ordinary contact views.'],['task.due','Scheduler / task','Scoped notifications; never arbitrary customer messages.'],['site.published','CMS / document','CDN invalidation, sitemap and publishing audit.'],['form.submitted','CMS / form_entry','CRM capture reconciliation and safe source metrics; no raw values on event bus.'],['campaign.enrolled','Marketing / enrollment','Create generation-bound scheduled actions.'],['campaign.cancelled','Marketing / enrollment','Invalidate unsent actions, preserve receipts.'],['delivery.receipt','Delivery adapter / delivery_attempt','Update terminal state, suppression/consent via explicit approved commands and aggregates.'],['consent.changed','Marketing / consent_event','Invalidate sending eligibility and cancel/suppress affected pending actions.'],['listing.changed','Property / listing','Search/cache update and licensed alert matching.'],['listing.withdrawn','Property / listing','Invalidate every public/cache/media/alert surface.'],['subscription.reconciled','Billing / subscription','Update explicit entitlement projection and provisioning state.'],['integration.state_changed','Integrations / integration_connection','Connector readiness notifications and safe job scheduling.'],['ai.draft_ready','AI / ai_job','Notify requester; no automatic content/action mutation.']])+
 p('Leases use a bounded lease_until and heartbeat, with conditional state/version updates. Claim one due action via transaction and row locking; release the database transaction before external calls. Persist an attempt and stable provider idempotency key before sending. A timeout after provider acceptance becomes unknown/reconciling; retry only after receipt/provider query or an explicitly approved manual decision. Provider keys may have finite windows, so local attempt history outlives them.'+cite('https://resend.com/docs/dashboard/emails/idempotency-keys','Resend delivery idempotency'))+
 p('Email unsubscribe links use signed purpose/channel tokens without requiring login; the dedicated one-click endpoint accepts the mail client POST form with token in the URL, no cookies/CSRF/session and no redirect. GET link previews never withdraw consent. Configure List-Unsubscribe/List-Unsubscribe-Post and provider DKIM coverage per RFC 8058; redact token query strings from access logs. Cancellation increments the enrollment generation and cancels future pending actions. A worker rechecks generation immediately before dispatch; cancellation cannot retract a message already accepted by a provider. Quiet hours and send dates use recipient timezone if known, otherwise approved organization default. For daylight saving gaps use the first valid instant after the gap, and for repeated times the first occurrence; expose computed send time in previews. Birthday on 29 February defaults to 28 February in non-leap years only after owner approval; do not silently invent greeting policy.'+cite('https://www.rfc-editor.org/rfc/rfc8058','RFC 8058 one-click unsubscribe'))+
 table(['Failure','Recovery and user state'],[
 ['Redis unavailable','Committed jobs remain in PostgreSQL. Recover due wakeups; show delayed pending status.'],['Worker crash before provider call','Expired lease resumes with same action/attempt identity after revalidation.'],['Worker crash after provider acceptance','Reconcile receipt/provider reference; do not blindly resend.'],['Outbox duplicate / consumer crash','Same event ID and consumer dedupe ledger prevent duplicate domain effects.'],['Provider 429 / 5xx','Respect Retry-After; bounded exponential backoff with jitter, circuit breaker and organization concurrency limit.'],['Permanent validation / rights / consent failure','Terminal safe error with actionable reason; no automated retry until state/input changes.'],['Database commit failure','No durable command outcome; retry with original idempotency key. Never return succeeded.'],['Poison job','Bounded attempts then quarantine/dead-letter with redacted context; operator replay is audited and revalidates current authorization.']]));

 section('mls','9. Las Vegas MLS and Trestle integration architecture',
 callout('<strong>Owner-selected provider: CoreLogic Trestle / Cotality Trestle.</strong> The owner supplied this choice during drafting. Public documentation confirms a RESO WebAPI path; no Las Vegas account, feed entitlement, participant approval or credentials have been verified. M1 freezes interfaces, M5 uses synthetic fixtures, and M6 connects the authorized Trestle feed.')+
 `<figure><img src="diagrams/mls-pipeline.svg" alt="MLS pipeline with provider capability checks, normalized records, durable checkpoints and policy gates"/></figure>`+
 p('Trestle’s current documentation identifies a Cotality API base, OAuth client-credentials authentication and OData metadata discovery. Configure token/data origins from the approved connection rather than hard-code legacy hostnames shown in older examples. Read the returned token expiry, cache server-side, refresh before expiration with a single-flight lock and keep secrets in Key Vault references. Do not assume refresh-token support.'+cite('https://trestle-documentation.corelogic.com/web-api/','Trestle WebAPI getting started'))+
 p('Target a Trestle RESO WebAPI adapter as the first live implementation, preferably licensed replication for native search when approved. Trestle documents real-time queries and replication; this does not prove the owner’s feed permits every resource, field, display status or use. Do not use its sample feed: the user’s development constraint remains our own fictional data.'+cite('https://trestle-documentation.corelogic.com/support/faq/','Trestle capabilities FAQ'))+
 table(['Transport mode','Data path','Product implications'],[
 ['Replication — preferred if licensed','Authorized Trestle change pages → normalize → tenant/feed-scoped PostgreSQL → search.','Native list/map/detail/organizer/alerts only within approved field, media, cache and notification rights.'],
 ['Live query','API → provider adapter with bounded filters → normalize approved response.','No assumed full local inventory. Short cache only if licensed; saved searches store criteria, not unrestricted listing snapshots. Alerts require an approved polling/provider mechanism.'],
 ['Embed — alternative provider capability','Public site loads an approved provider origin and documented integration surface.','Native search/map/organizer may be unavailable or provider-owned. Approved inquiry integration may route to CRM; no assumed postMessage events, scraping or listing ingestion. Trestle embed support is not claimed.']])+
 p('The '+link('contracts/mls-adapter.ts','type-only MLS adapter contract')+' discriminates these modes, capabilities, normalized listing identity, secret access and display policy. It is a specification, not an implemented connection. Future regional providers implement the same ports; do not share feed rows across organizations unless both licensing and access policies explicitly permit it. RESO defines standards rather than granting data access.'+cite('https://www.reso.org/reso-web-api/','RESO Web API'))+
 `<h3>Trestle-specific synchronization plan</h3>`+
 p('Use ModificationTimestamp for property changes and PhotosChangeTimestamp for media refresh planning. Trestle explains that incremental updates alone do not discover records that disappear; implement complete authorized key reconciliation. A partial/failed key scan must never be interpreted as deletion. Use a scan generation, commit the complete seen-key set, and only then withdraw absent keys. Bound mass-update concurrency and make progress visible.'+cite('https://trestle-documentation.corelogic.com/web-api/at-scale/','Trestle scaling and reconciliation'))+
 p('Follow @odata.nextLink as an opaque approved-origin continuation. Use Trestle’s documented replication extension when appropriate rather than synthesize arbitrary skip offsets. Compile filters from a typed allowlist and encode values; never accept raw client OData expressions. Confirm OData resource/enum metadata for the approved feed and preserve source names where normalization differs.'+cite('https://trestle-documentation.corelogic.com/web-api/reference/','Trestle query reference'))+
 table(['Concern','Implementation rule'],[
 ['Feed identity / credentials','mls_feed stores provider=trestle, approved connection reference, mode, policy/mapping version and health; secrets live outside ordinary tables. A worker resolves credentials from its verified tenant/feed context, not from a user-supplied URL.'],
 ['Initial load','Persist a run and request boundary; fetch a bounded page, schema-validate and normalize, transactionally upsert by source key and emit changed/withdrawn references. Advance the page checkpoint only after that page’s commit. Idempotent replay is mandatory.'],
 ['Incremental watermark','Use source timestamps, deterministic key tie-breakers when supported and configurable overlap; do not use the worker clock as the last-source-update watermark. Track latest fully processed boundary, not the largest timestamp seen before failure.'],
 ['Pagination security','Validate every returned next-link origin/path against the connection allowlist before attaching tokens. Reject redirects to unknown/private hosts. Expired continuation restarts a bounded overlapping run with idempotent upserts.'],
 ['Status / deletion','Map StandardStatus plus source-specific restrictions. Active/pending/closed visibility depends on licensed policy; unknown statuses fail closed. Reconciliation handles missing/deleted/Internet-withheld records and invalidates search, map, details, media, SEO, featured blocks and alert work.'],
 ['Media','Use provider URLs, approved signed proxy or licensed copied images according to contract. Store source media key/order/change timestamp and expiry. Scan permitted downloads, use bounded transforms and remove derived copies on withdrawal/termination. Never treat a publicly reachable MediaURL as permission to retain it.'],
 ['Search / maps','PostGIS/text filtering and normalized criteria are shared by list and map. Enforce result/extent limits. Suppressed address also suppresses exact coordinates, structured data, accessible image text and SEO metadata unless policy explicitly permits a different projection.'],
 ['Alerts','Unique match key includes tenant/feed/listing/source change/search/preference generation. Recheck latest listing and feed rights plus current visitor preference/consent at delivery. A detail link that later withdraws shows unavailable, not a stale snapshot.'],
 ['Inquiry / attribution','Resolve listing server-side under current display policy, capture feed/listing/source identifiers, campaign/source context and published form version, then create one CRM contact/lead activity through the shared capture command. Never trust caller-provided brokerage or assigned agent IDs.'],
 ['Quota / retry','Discover the connection’s API and media budgets from approved docs/response headers; configure token buckets per connection and separate media work. Do not treat public example quotas as this account’s quota. Respect 429/Retry-After; bounded backoff/circuit breaker and safe health states.'],
 ['Auth failure','One synchronized token renewal after a genuine expiry; repeated 401 disables the connection and alerts an operator. Do not endlessly retry revoked/invalid credentials or log Authorization.'],
 ['Freshness','Approved refresh interval, allowed maximum age, source delay and retention are separate fields. Unknown max age blocks live activation. Data past allowed age is unavailable; a generic stale label cannot authorize prohibited display.'],
 ['Partner display policy','Versioned rights matrix includes required attribution/logo/disclaimer/links, statuses, fields, address/coordinates, media/cache/alerts/AI rights, retention and purge rules. Screenshots and source-to-display checks are M6 evidence.'],
 ['Monitoring','Per-feed last successful page/run/reconciliation, source freshness distribution, failed pages, lag, quota resets, mapping rejects and withdrawal propagation. Redacted traces include source key references where permitted; no private source payload dump.'],
 ['Termination / revocation','Disable serving immediately, cancel unsent alerts, invalidate caches/search and purge storage per approved rules. Keep minimal permitted audit references. Restore drills cannot reenable a revoked feed.']])+
 `<h3>Canonical field mapping baseline</h3>`+table(['Provider field / metadata concept','Platform mapping','Validation / policy'],[
 ['ListingKey + originating/source system','source_listing_key within approved tenant/feed; retain board/system mapping reference.','Do not infer globally unique keys across feeds.'],['StandardStatus; MlsStatus','status + source_status + mapping version.','Unknown/off-market non-displayed unless approved.'],['ListPrice / currency','Decimal listing price in major currency units; billing uses integer minor units separately.','Nonnegative, explicit currency metadata; missing price remains unknown.'],['Beds/Baths / LivingArea / unit metadata','bedrooms, bathrooms, area value/unit.','Fractional baths supported; missing values not fabricated as zero.'],['Address / Latitude / Longitude / Internet-display fields','Approved public address/location projection and independent display flags.','Mask before serialization, caching, map, SEO and AI retrieval.'],['PublicRemarks','Sanitized public remarks.','No confidential/private remarks; allowed length and AI-use policy.'],['ListOffice / ListAgent resources where allowed','Approved brokerage/agent attribution projection.','Required attribution is not silently replaced by tenant branding.'],['ModificationTimestamp / PhotosChangeTimestamp','Source update/media-change checkpoints, ingestion time and policy-derived expiry.','Source watermark, not local current time.'],['Media key / URL / order','listing_media references or licensed derivative.','Allowlisted origin; image rights and expiry independent of listing display.']])+
 p('Field names are the planned standards mapping, not proof all fields exist in the Las Vegas connection. Snapshot authorized metadata and map fixtures at M6. Unit tests must cover nulls, unknown enum values, status transitions, duplicate/equal timestamps, partial pagination, media reorder/deletion, missing geolocation, suppressed addresses and schema changes.')+
 `<h3>M6 owner/provider inputs — requested only when that milestone starts</h3>`+p('Approved Trestle product/connection and MLS participant permissions; actual Las Vegas board/feed identifiers; current contract/display rules; endpoint and resource metadata; credentials delivered through the secret manager; quota and refresh terms; permitted statuses/fields/media/cache/alerts/AI/retention; attribution assets; support escalation and acceptance process. Public provider selection is already recorded and does not replace these approvals.')+
 p('Until then, '+link('fixtures/synthetic-listings.json','12 fictional listing fixtures')+' and the future mock adapter exercise the exact public application contracts. Freeze the fixture clock. Every sample card/detail/map and no-delivery alert preview displays “SYNTHETIC SAMPLE DATA”. No live feed access, Trestle sample-data download or restricted MLS scrape is authorized by this document.'));

 section('flows','10. Integrated workflow specifications',
 table(['Flow / actor','Command and durable result','Failure / acceptance'],[
 ['FL-01 · Public lead capture','Verified published site/form → validate fields and explicit purpose consent → shared CRM capture transaction → form entry/contact/lead/source activity/outbox → receipt → eligible routing and notification.','Duplicate submit returns one receipt/lead; disallowed form fields fail; abuse checks cannot silently create permission. Both form and inquiry use the same capture port.'],
 ['FL-02 · Lead assignment and follow-up','Manager publishes versioned routing rules → capture applies first-touch/listing-agent/geography/weighted-round-robin → eligible active member or unassigned → agent sees scoped lead and adds task/note.','Concurrent assignments serialize selection state; unavailable member yields documented fallback. Task and stage changes enforce optimistic version/scope.'],
 ['FL-03 · Website draft to publish','Editor saves new immutable revision → preview resolves draft only for permitted editor → publisher confirms expected document/revision → atomically swap published pointer → durable CDN/sitemap job.','Stale revision returns 412/conflict UI; missing media scan or unknown block prevents publication. Rollback selects an existing same-document revision, with audit.'],
 ['FL-04 · Campaign preview to delivery','Editor drafts graph/message → publisher validates graph and publishes immutable version → sender previews eligible audience/time/cost → confirm durable enrollment/broadcast → dispatch revalidates consent/readiness → provider receipt.','Queued is visibly queued. Unknown provider acceptance reconciles; opt-out blocks future work; no real send in dev/staging transports.'],
 ['FL-05 · Property search to inquiry','Site resolves mode/policy → shared filters produce list/map → approved details/attribution → visitor submits inquiry → CRM source/listing provenance and routing.','Denied/expired listings return unavailable without hidden fields. Embed-only adapter never impersonates native inventory. Samples remain conspicuous.'],
 ['FL-06 · Saved search to alert','Verified site-bound visitor saves criteria/frequency → listing event creates deduped match → current policy/preference/consent check → licensed email/SMS alert → safe deep link.','Withdrawn or expired data cancels pending matches; visitor A cannot read B searches; preference off is immediate for future sends.'],
 ['FL-07 · Billing change','Billing admin receives current priced preview and expiry → explicit confirmation with idempotency → hosted financial flow → verified webhook/current-state reconciliation → explicit entitlements/provisioning.','Changed/expired preview fails; out-of-order events cannot regress entitlement state. Financial provider failure leaves pending/failed, not unlocked features.'],
 ['FL-08 · AI draft review','Permitted requester selects source facts/purpose → scope/rights/cost gate → structured draft job → validate citations and warnings → human edits/accepts with destination version → save draft.','No auto publish/send/consent/billing. Refusal/schema error/permission revocation leaves source unchanged.'],
 ['FL-09 · Install and mobile work','Browser user opens workspace → optional install guidance → standalone launch → same verified organization/API permissions → full responsive commands and in-app status.','No store dependency. Offline shell explains connection need; requests interrupted after commit reconcile idempotently on reconnect.'],
 ['FL-10 · Staff support','Staff opens safe organization health → authorized purpose-bound grant → scoped customer context with banner → approved diagnostic/replay command → append audit → grant expiry/revocation.','Generic rerun cannot resend unknown messages. No grant means no CRM access; expiration enforced by API, jobs and download gateways.']])+
 p('E2E tests reference these flow IDs plus module acceptance IDs. Integration ownership covers the complete boundary, not merely isolated screens. Test public/domain resolution, callback origins, tenant switching and provider-degraded outcomes with deterministic mocks before any live provider acceptance.'));

 section('design','11. Premium UI/UX and reusable design system',
 p('The proposed visual language uses a quiet neutral canvas, dark navy navigation, restrained blue actions and semantic teal/amber/red states. It is independently designed. Use the '+link('design-system/tokens.json','JSON tokens')+' and '+link('design-system/tokens.css','CSS tokens')+' as a single source; brand changes update tokens rather than per-module CSS.')+
 `<figure><img src="diagrams/workspace-wireframe.svg" alt="Original CRM workspace proposal with organization switcher, filters, lead list and detail panel containing invented records"/><figcaption>Original workspace concept; all displayed contacts are invented. This is a design diagram, not a screenshot of a working app.</figcaption></figure>`+
 table(['Navigation level','Behavior'],[
 ['Primary workspace','Home, CRM, Websites, Marketing, Properties, Reports, Integrations, Settings, Support. Entitlement gates explain unavailable features; hide only unauthorized routes. Do not replace a gated feature with a misleading empty dataset.'],
 ['Header','Active organization, scoped search, help, in-app notifications and profile. Organization switch is always visible on desktop and available in the mobile header. Global search shows resource scopes explicitly.'],
 ['Module subnavigation','CRM: leads/contacts/deals/tasks/imports. Websites: sites/pages/media/forms/domains. Marketing: campaigns/designs/automations/delivery. Properties: search/feed health. Settings: organization/team/roles/billing/preferences.'],
 ['Staff workspace','Separate /staff shell and step-up session, organization health and grant controls. A granted customer context has a persistent purpose/expiry banner. No ambiguous “impersonation” mode.'],
 ['Public sites','Independent template navigation, approved search and organizer; attribution where required. No CRM/staff controls or workspace cookies on a custom-domain site.']])+
 table(['Layout / token','Specification'],[
 ['Desktop ≥1200px','240px sidebar; 64px header; 24px page gutters; maximum 1440px content. List/detail split with 360–420px drawer; primary action in consistent top-right location.'],
 ['Tablet 768–1199px','Collapsible navigation drawer; 16–24px gutters; two-column cards where readable. Builder property pane switches to tabs; map/list toggle preserves filters.'],
 ['Mobile 360–767px','Home/Leads/Tasks/More bottom navigation plus organization header. Safe-area padding and dynamic viewport height; full-screen detail drawers, labeled back actions, card/list table alternatives and sticky primary action above the keyboard.'],
 ['Typography','Inter or system fallback; body 16px/1.5, dense table 14px, caption 12px only for secondary metadata, H1 32px, H2 24px, H3 18px. Load a licensed local font with swap; no text embedded in images.'],
 ['Spacing / shape','4/8/12/16/24/32/48/64px rhythm; control radius 8, card 12, dialog 16. Keep information aligned; use modest shadows only for overlays.'],
 ['Interaction','44px desired touch targets; desktop compact rows 40px and comfortable rows 52px. 120–180ms motion with reduced-motion support. Native scrolling and obvious click affordances.'],
 ['Colors','Canvas #F5F7FB; surface #FFFFFF; ink #172238; muted #52617A; primary #2459B8; navy #15263F; semantic colors specified in token file. Use text/icons as well as color for status.']])+
 `<h3>Component contract</h3>`+table(['Component','Required behavior / implementation notes'],[
 ['DataTable / MobileRecordList','Typed column registry, server pagination/filtering, visible scope, stable selection, sortable keyboard headers, empty/loading/error rows. Bulk actions preview eligible records and repeat permission checks; never infer all pages from visible selection.'],
 ['Forms / Field / ErrorSummary','Persistent visible labels, help and inline errors, required semantics, autocomplete/inputmode, 16px mobile inputs, linked error summary and preserved values. Async validation does not unexpectedly move focus.'],
 ['Dialog / Drawer / ConfirmPreview','Focus trap and return, Escape unless safe blocking flow, descriptive heading, scrollable body and visible actions. Financial/send/publish previews show scope, consequences, pending state and version/expiry.'],
 ['StatusBadge / JobPanel / Toast','Statuses have text/icon. Toasts summarize transient success; persistent job/error panels hold unresolved failures. Screen-reader status announcements are concise and do not interrupt typing.'],
 ['MetricCard / ReportChart','Name/unit/source/period/definition/freshness; explicit unknown/unavailable/stale states. Chart has text summary and accessible data table; no unexplained composite score or artificial hours-saved value.'],
 ['CRMRecord / Timeline / Pipeline','Lead/contact distinction, clear owner/stage/next action, communication eligibility and chronological history. Dragging stages has a keyboard/menu alternative with the same transition command.'],
 ['BuilderCanvas / BlockInspector','Three-pane desktop; one-pane mobile with block list, field inspector and preview tabs. Add/reorder/remove via buttons and keyboard. Dirty/saved/published states, accessible responsive previews and conflict recovery.'],
 ['EmailDesigner / MobileMessageForm','Lazy licensed editor on compatible devices; native template/merge-field form and text/HTML preview allow the same edit/review/publish actions on mobile. Reject an editor that requires desktop for essential launch tasks.'],
 ['WorkflowCanvas / OrderedWorkflow','Typed node/edge editor with accessible ordered list/branch form. Show timezones, calculated delays, restart policy and validation. Limit graph complexity; canvas gestures are optional.'],
 ['PropertySearch / ListingCard / MapPanel','Shared criteria and result count, list/map switch, filter drawer, image placeholders, freshness/attribution, sample banner, saved preference and inquiry. Keyboard list remains functional when map fails.'],
 ['InstallPanel / UpdateNotice / OfflineScreen','Correct platform installation steps, standalone awareness, safe waiting-worker updates and truthful connectivity. Installation/push permission never blocks ordinary web use.'],
 ['Permission/Plan/Connector panels','Explain role scope, limits and available/connected/degraded states. Deep links remain guarded; hidden controls do not constitute security.']])+
 `<h3>State specification</h3>`+table(['State','UI requirement'],[
 ['Initial loading','Skeleton matches intended geometry; aria-busy on region; no premature zero metrics.'],['Empty / first use','Explain what is absent and present one permitted next action; distinguish zero results from no initial setup.'],['Filtered empty','Keep current filters visible and offer clear filters.'],['Success','Confirm completed server state; durable jobs show queued then terminal state.'],['Validation / conflict','Inline specific errors; preserved input; version conflict offers review/reload without silently discarding work.'],['Permission / entitlement','Readable reason and permitted next step; no leaked resource details or purchase pressure when a role lacks access.'],['Provider degraded','Last valid timestamp only where rights permit; disabled affected action and recovery guidance.'],['Offline / reconnect','Connection indicator, generic offline page, disabled new durable commands, pending outcome reconciliation.'],['Partial report / media error','Explicit missing-source/placeholder state, not substituted zero or unrelated stock property image.'],['Fatal page error','Scoped retry and trace ID; no stack trace/private provider payload.']])+
 p('Target WCAG 2.2 AA: 4.5:1 normal text, 3:1 large text and necessary component boundaries, visible focus not obscured, keyboard alternatives, accessible authentication and robust status/error semantics. Our 44px touch target is a product target above the criterion’s 24px minimum with exceptions; it is not the WCAG minimum. An accessibility overlay cannot replace testing of the base interface.'+cite('https://www.w3.org/TR/WCAG22/','WCAG 2.2'))+
 table(['Measured proposed color pair','Foreground','Background','Contrast'],contrastPairs.map(x=>[e(x.name),code(x.foreground),code(x.background),e(x.ratio+':1')]))+
 p('These are computed token contrasts, not a completed application accessibility audit. Verify real hover/focus/disabled states, charts, embedded editors, zoom at 200%, reflow, VoiceOver/TalkBack and keyboard workflows during implementation.'));

 section('pwa','12. Full web application on iPhone and Android — no app stores',
 callout('<strong>Mandatory owner requirement:</strong> the complete product is a web application and an installable home-screen app on iPhone and Android. Distribution is HTTPS and browser installation; no Apple App Store or Google Play release, native wrapper or separate native codebase is required.')+
 p('Use Next.js manifest support and a small reviewed service worker. The workspace origin is the primary installable app; public agent sites remain fully responsive browser experiences and may optionally have their own independent manifests later. A workspace installation does not carry a customer site’s branding or merge cross-origin sessions.'+cite('https://nextjs.org/docs/app/guides/progressive-web-apps','Next.js PWA guide'))+
 p('iPhone guidance uses the browser share/menu path to Add to Home Screen; Android uses the browser’s Install/Add to Home Screen capability. Show a platform guide when no programmatic install event exists, and hide prompts after standalone launch. Safari 26 also expands web-app installation behavior, so capability checks and current device testing are preferable to a rigid user-agent-only rule.'+cite('https://web.dev/learn/pwa/installation','Browser installation behavior')+cite('https://webkit.org/blog/17333/webkit-features-in-safari-26-0/','Safari 26 web-app changes'))+
 table(['PWA contract','Implementation'],[
 ['Manifest / icons','Stable id, name/short_name, start_url=/dashboard, scope=/, display=standalone, theme/background colors. Original 192/512 PNG, separate maskable 512 and Apple touch icon; owner-approved brand. '+link('contracts/pwa-manifest.example.json','Manifest specification example')+' references future icon deliverables, not existing app assets.'],
 ['Shell / navigation','Same authenticated app and module permissions. Safe-area insets, 100dvh with fallback, orientation/keyboard-aware controls, readable forms and touch targets. Do not rely on browser back chrome in standalone mode.'],
 ['Mobile functional parity','Every entitled core command has a 360px path, including content editing/publishing, message/workflow editing and billing/settings. Use forms/lists where a canvas or third-party editor is unsuitable; mobile is not a read-only companion.'],
 ['Offline initial scope','Static shell, local safe assets and generic offline guidance only. No persistent private business data or queued offline writes. In-memory unsaved inputs may survive brief disconnects but not OS process eviction; communicate that limit.'],
 ['Service-worker network policy','Allowlist hashed safe assets. Never cache authentication, API responses, personalized HTML/RSC, CRM, billing, AI, signed downloads or MLS pages/media. Do not apply a catch-all navigation cache. '+link('contracts/pwa-policy.json','PWA cache/update policy')+'.'],
 ['Mutation recovery','If connection drops after a submit, preserve the command idempotency key and query outcome after reauthentication/reconnection. Refetch current versions/scope; unknown is never saved. Initial release disables new offline financial/send/publish/edit commands. Authenticated API and personalized HTML/RSC responses also use Cache-Control: private, no-store; service-worker exclusion alone is insufficient.'],
 ['Updates','Serve SW/manifest with controlled revalidation; content-hashed static assets. A waiting update shows notice and activates after user acceptance/safe idle, with dirty-draft/in-flight-command guards. Delete only obsolete non-sensitive caches.'],
 ['Auth / hosted providers','Test OIDC callback and Stripe return in browser and standalone contexts; external links may use browser context. Return to a signed allowed deep link, preserve job reference, and reauthenticate when session state is unavailable. No embedded payment/identity assumption.'],
 ['Push / badges','Opt-in feature-detected Web Push and optional badging. Device record bound to active member/tenant and preference topics; in-app inbox authoritative. Generic lock-screen text such as “You have a new workspace update”, no contact names/addresses.'],
 ['Push transport security','Server-held VAPID private key; encrypted endpoint/keys; vetted HTTPS egress destinations, no arbitrary URL fetch. Remove invalid/410 devices and revoke on removal/logout/membership revocation. A notification click uses an allowlisted same-origin path and normal authorization.'],
 ['Background limits','All business scheduling runs on server workers. Do not depend on iOS/Android keeping a tab or service worker alive, background sync availability, silent push or push delivery guarantees.'],
 ['Device acceptance','Physical iPhone Safari browser + home-screen app and Android Chrome browser + installed app, current and previous supported OS/browser versions at release. Desktop Chrome/Edge/Safari/Firefox browser compatibility; Playwright emulation supplements physical checks.']])+
 p('WebKit documents home-screen Web Push on supported iOS versions and a permission request triggered by direct user interaction. Installing alone does not grant notification permission. Unsupported or denied push still leaves the complete app and in-app inbox usable.'+cite('https://webkit.org/blog/13878/web-push-for-web-apps-on-ios-and-ipados/','WebKit home-screen push'))+
 p('M1 includes manifest/SW/cache seams; M2 validates CRM and account mobile workflows; each later module passes mobile command parity; M8 verifies physical installs, safe areas, keyboard, authentication, push denial/revocation, offline behavior and update recovery. Public hosting and icons are future implementation work; this TDD does not claim an installable app exists yet.'));


 section('metric-definitions','12a. Versioned reporting metric definitions',
 table(['Definition ID','Numerator / measure','Denominator / window / exclusions'],[
 ['MET-LEAD-CAPTURED-v1','Distinct committed lead IDs created in selected period.','No denominator. Dedupe capture/event IDs; retain anonymized counts after archival. Scope before aggregation.'],
 ['MET-CONTACT-RATE-v1','Distinct captured-cohort leads with an approved logged call or submitted email/SMS attempt within 7 days of capture.','Distinct leads in that capture cohort. Zero denominator is unavailable, not 0%; newest cohorts flagged incomplete. Notes/tasks alone are not contact attempts.'],
 ['MET-STAGE-CONVERSION-v1','Distinct cohort leads entering the selected target stage within 30 days.','Distinct cohort captured leads, with documented stage mapping. Separate cohort conversion from same-period transition counts.'],
 ['MET-PIPELINE-VALUE-v1','Sum open deal estimated amounts by currency as of period end.','No denominator; exclude closed/lost deals. Never mix currencies or label estimates as booked revenue.'],
 ['MET-DELIVERY-RATE-v1','Unique provider-confirmed delivered message attempts.','Unique accepted/submitted attempts in the documented send cohort; show pending/unknown separately. Provider privacy opens are not delivery or reading proof.'],
 ['MET-CLICK-RATE-v1','Unique eligible clicked attempts after approved bot filtering.','Delivered attempts in send cohort within proposed 7-day window; publish filter/version and unknown coverage.'],
 ['MET-WEB-SESSION-v1','Consented pseudonymous sessions under approved inactivity window, proposed 30 minutes.','No denominator. Collection coverage/blocked tracking shown; no complete-visitor claim. Paths exclude query strings and PII.'],
 ['MET-FORM-CONVERSION-v1','Committed submissions to a published form/version.','Consented form views of that version/window; mismatched collection coverage produces unavailable/qualified estimates.'],
 ['MET-PROPERTY-ENGAGEMENT-v1','Unique approved listing views and inquiry submissions.','Counts and per-view inquiry rate only where licensed analytics/consent and compatible windows exist. Source/feed/status and sample/live are distinct.'],
 ['MET-LOCAL-COVERAGE-v1','Supported publishers with provider-confirmed healthy synchronization.','Supported/contracted publishers, excluding unavailable capabilities. This is directory coverage, not AI-answer visibility.']])+
 p('Public collectPublicAnalytics accepts a bounded typed batch only under verified site and analytics-purpose consent. Validate document/listing references and current rights; client timestamps are untrusted and clamped to the approved window, while server ingestion time governs processing. Dedupe site/clientEventId; reject URL query strings and personal fields. Store safe references in activity_event payload and aggregate metric_snapshot, with no unrestricted CRM message or form body. Browser event IDs do not authorize visitor/CRM access. Metric windows and definitions are versioned product defaults requiring owner approval at M2/M7.'));
 const metricSection=sections.pop();
 const moduleSection=sections.find(s=>s.id==='modules');
 moduleSection.html=moduleSection.html.replace('<article class="module" id="MOD-H">','<article class="module"><h3 id="metric-definitions">Initial reporting metric definitions</h3>'+metricSection.html+'</article><article class="module" id="MOD-H">');
 section('ai','13. AI opportunities, safeguards and evaluations',
 table(['Use case','Inputs / output','Release decision / review'],[
 ['Page and blog copy','Approved business/profile/content facts → schema-bound draft with source IDs, warnings and tone.','M7 first wave; human saves as draft and separately publishes.'],['Property description assistance','Only listing fields licensed for AI use → draft description citing facts.','M7 only after M6 rights approval for live data; no invented amenities/prices/school claims. Synthetic data during development.'],['Campaign creation','Approved audience intent, templates and marketing facts → draft nodes/message designs.','M7 first wave; graph/merge/content checks, human publication and separate send preview.'],['Lead qualification assistance','User-provided intent/timeline and allowed activity → summary and suggested follow-up questions.','Describe expressed intent, not housing/credit eligibility. No protected-trait inference, ranking by demographic proxy or autonomous disqualification.'],['CRM workflow recommendations','Scoped lead/task history → recommendations and rationale.','Suggestions only; a user creates tasks/transitions through ordinary guarded commands.'],['Conversational website assistant','Published site facts and licensed public listings → grounded answers and explicit contact handoff.','Later opt-in after public retrieval evaluation, abuse limits and owner policy. No private CRM tools, arbitrary URL fetch or hidden browsing.'],['Analytics insights','Versioned metric snapshots → descriptive summary with IDs/window/definitions.','M7; explicitly state missing coverage and uncertainty; no fabricated causal or revenue attribution.'],['Review response assistance','Approved review/profile context → reply draft.','Optional M7 provider-capability gate; no automatic posting or fake review generation.']])+
 p('Request flow: validate ai.use plus all source read permissions → build minimal tenant-scoped context → reject unlicensed listing use → enforce budget → call provider with configured model/prompt version and strict JSON Schema → handle refusal/incomplete output → validate schema, citation IDs and safety constraints → store expiring draft → human acceptance with destination draft permission/version. Database facts and retrieved text are untrusted content, never higher-priority tool instructions.')+
 p('Structured Outputs improves schema adherence but does not prove factual correctness. Validate claims against approved source facts, handle refusals, and separate evaluation from runtime schema validation. Use Responses text.format with a strict schema or the supported SDK equivalent selected at M7; no credential is required for the blueprint.'+cite('https://developers.openai.com/api/docs/guides/structured-outputs?api-mode=responses','Structured Outputs limitations'))+
 p('Choose model by quality/cost/latency measurements on the platform’s datasets, then pin deployment configuration and prompt/schema versions. Provider retention and regional processing require an approved data agreement. store:false is not a zero-retention guarantee; verify actual account controls and provider terms before sending sensitive customer data.'+cite('https://developers.openai.com/api/docs/guides/your-data','OpenAI data controls'))+
 table(['Proposed release evaluation gate','Target / evidence'],[
 ['Schema and permission enforcement','100% of accepted drafts pass server schema and citation-reference validation; zero cross-tenant or out-of-scope disclosures in negative tests.'],['Factuality','No unsupported critical property/financial claim in the evaluation set; at least 95% supported fact assertions in reviewed sampled drafts. These are project targets, not achieved scores.'],['Human control','100% of acceptance tests save drafts only; zero automatic publish/send/billing/consent actions.'],['Safety / injection','Adversarial listing/page instructions cannot execute tools or access private facts. Eligibility/protected-trait requests decline inappropriate classification and offer allowed intent summaries.'],['Useful abstention','Missing facts and source denial produce clear abstention/warnings, never fabricated answers. Include refusal and truncated-output fixtures.'],['Cost / latency','Approved per-purpose token/output ceiling and tenant monthly budget; record measured p50/p95 and cost before enabling the feature. No price estimate without selected current model/pricing.'],['Dataset / review','Minimum initial 200 synthetic/redacted cases distributed across purposes, failure states, tenants and adversarial inputs; version rubric, results and human reviewer disposition.']])+
 p('AI worker cannot use domain write/publish/send credentials. Allowed tools, if introduced later, are read-only scoped ports with schema validation and egress restrictions. Retrieval never follows arbitrary URLs from listing remarks or user instructions. Audit references capture model/prompt/context IDs and review outcome without duplicating unrestricted customer data in telemetry.'));

 section('integrations','14. Integration boundaries and procurement gates',
 table(['Capability','Build / buy decision','Gate and facts'],[
 ['Identity','Buy OIDC identity; build organization authorization.','Entra External ID proposed M1; test issuer/subject/callback/session behavior. Reference B2C observation is not a new service choice.'],['Billing','Stripe hosted flow; native plan metadata/entitlements/reconciliation.','M2 sandbox and commercial setup. Plan catalog uses code + billing interval variants. Referenced provider prices are verified server-side; price/interval changes create a new catalog version/code instead of rewriting an active subscription price. Plan feature metadata changes do not silently change existing subscriptions or entitlements.'],['CRM / routing','Build native.','M2 own data model and all scope tests; no dependency on the reference white-label CRM.'],['CMS / templates','Build native models/rendering; Puck editor adapter.','M3 review editor license, mobile parity, block migration and sanitization.'],['Email designer','License Unlayer behind adapter.','M4 verify export, mobile fallback, licensing/seat limits and sanitization. If terms unsuitable, use simpler native templates through same contract.'],['Email / SMS','Resend / Twilio proposed; native consent/workflow.','M4 verifies senders, receipts, signatures, quotas, messaging policy and no-delivery tests.'],['Las Vegas MLS','Owner-selected Trestle RESO WebAPI adapter.','M1 seam; M5 synthetic mock; M6 actual account metadata, feed product, licensing and current board rules.'],['Maps / geocoding','MapLibre plus contracted provider.','M5 tile/geocoding rights, quotas and attribution; use invented coordinates in fixtures.'],['Local directory network','Yext proposed adapter.','M7 procurement and exact capabilities; reference observed Yext does not supply our subscription.'],['Scheduling','Calendly or owner-approved provider adapter.','M2/M4 verify webhook availability/plan and timezone/cancellation semantics; iframe presence alone is not CRM sync.'],['Web Push','Standards-based browser transport + native device registry.','M2–M8 opt-in and physical-device tests; not required for app use or business scheduling.'],['AI','OpenAI Responses API behind adapter.','M7 model/pricing/data controls/evaluations verified then.'],['Storage / CDN / DNS','Managed Blob/CDN/TLS/DNS adapters.','M3 scan, signed grants, exact domain ownership and purge verification.'],['Helpdesk / social / advanced creative','Native tickets first; other providers deferred.','Only implement selected and procured capabilities, with explicit permission/event contracts.']])+
 p('Every provider adapter has a server-only port, mock/no-side-effect implementation, contract tests, health state, capability description, typed errors, timeout/quota policy and credential-reference lifecycle. Unknown commercial rights keep a feature disabled. Available catalog choices, connected accounts and verified working integrations are separate UI states. OAuth disconnect revokes credentials where possible and prevents future jobs immediately.'));

 section('repository','15. Future repository and agent coordination',
 p('This structure is the proposed implementation repository, not scaffolding already created. The current workspace contains only design artifacts and the earlier audit. Commit '+link('future-repo/AGENTS.md','the AGENTS.md specification')+' at the future repository root when implementation begins.')+
 `<pre>${e(repoTree)}\n  apps/web/app/manifest.ts\n  apps/web/public/{sw.js,offline.html,icons/}\n  apps/web/features/pwa/{InstallGuide,UpdateNotice,PushSettings}.tsx\n  packages/providers/push/{port.ts,mock.ts,web-push.adapter.ts}\n  tests/e2e/pwa/\n  docs/runbooks/mobile.md</pre>`+
 p('A module uses module.ts/controller.ts/service.ts/repository.ts plus dto/ports/policies/tests. UI owns presentation only; domain commands live in API/services. Shared contract generation emits clients under packages/contracts/generated, which are never manually edited. packages/db owns migrations and transaction context; providers own external transport, not CRM semantics.')+
 table(['Shared surface','Owner / coordination rule'],[
 ['OpenAPI, event and permission contracts','W01 owns; affected module owner approves semantic changes. Commit additive contract PR first, regenerate and test consumers.'],['Database migrations and RLS','W01 owns migration registry/security; module owner supplies entity/query needs. W11 verifies upgrade/role behavior. No competing migrations with identical IDs.'],['Tokens, shell and shared UI','W02 owns; W12 reviews mobile/PWA behavior. Module-specific components remain in feature directories.'],['Outbox/event envelope','W01 infrastructure; W08 definitions/projections; producer/consumer owners review events. No unrestricted payload or hidden direct-table integration.'],['Root dependencies and lockfile','W11 owns coordinated updates with W01 security review. Feature agents request additions rather than concurrently rewrite lockfile.'],['Release branch / deploy / infrastructure','W11 owns integration sequence, CI and runbooks. Owner-authorized release gate applies at M8; passing a feature PR is not release approval.']])+
 p('Use one branch/worktree per workstream, small dependency-ordered PRs and CODEOWNERS for shared surfaces. Worktrees isolate changes; they do not share a writable application checkout. A detached worktree needs a branch before PR submission. Never copy production secrets/customer exports into worktree bootstrap. Contract stubs and mocks let consumer UI/worker tasks proceed after interfaces freeze.'+cite('https://learn.chatgpt.com/docs/environments/git-worktrees','Codex worktree conventions'))+
 p('AGENTS.md gives repository rules; nearer directory instructions may specialize ownership/testing. Keep the root file concise and link detailed TDD/runbooks instead of duplicating the entire document; Codex applies instruction files according to directory scope.'+cite('https://learn.chatgpt.com/docs/agent-configuration/agents-md','Codex AGENTS.md conventions'))+
 p('Integration owner maintains a contract/migration changelog and requirements-to-test ledger. PRs specify requirement IDs, behavior, contract changes, validation evidence, operational risks and rollout compatibility. Contract-breaking changes require an ADR and coordinated consumers; no silently divergent handwritten API types. Cross-module flows FL-01–FL-10 gate integration, including mobile/browser parity.'));

 const wsModules={W01:['MOD-A'],W02:['MOD-B','MOD-K'],W03:['MOD-A','MOD-B','MOD-J'],W04:['MOD-D'],W05:['MOD-C'],W06:['MOD-E'],W07:['MOD-F'],W08:['MOD-G'],W09:['MOD-H'],W10:['MOD-I','MOD-J'],W11:modules.map(m=>m.id),W12:['MOD-K']};
 const wsTech={W01:'NestJS guards, PostgreSQL/PostGIS, Drizzle, OpenAPI/JSON Schema, OIDC; W11 CI.',W02:'React/Next.js, TypeScript, Tailwind 4, Radix, TanStack Table/Query; no provider calls in components.',W03:'NestJS/Next.js, OIDC, Stripe adapter, tenant commands, job/status projections.',W04:'NestJS repositories, tenant transactions, CSV parser/writer, deterministic rule engine; Next.js CRM views.',W05:'Next.js server rendering, Puck adapter, block schemas, Blob scan/transform, CDN and domain/TLS ports.',W06:'BullMQ/PostgreSQL schedule, virtual clock, Unlayer adapter, Resend/Twilio ports, receipt verifier.',W07:'MLS TypeScript ports, packages/providers/mls/trestle/trestle.adapter.ts and trestle.mapper.ts, Trestle OData compiler, PostGIS, MapLibre/tile adapter and synthetic fixtures.',W08:'PostgreSQL aggregations, versioned metric definitions, safe events and TanStack/chart components.',W09:'OpenAI Responses adapter, strict schemas, scoped retrieval, prompt/model registry and evaluation runners.',W10:'Typed Yext/calendar/DNS ports, signed callbacks, reconciliation jobs and safe health errors.',W11:'Terraform, OCI images, CI, real PostgreSQL test roles, k6, Playwright/axe, OpenTelemetry and restore drills.',W12:'Next.js manifest, reviewed service worker, Web Push/VAPID port, safe responsive UI and physical-device tests.'};
 section('workstreams','16. Workstreams — twelve implementation fields each',
 p('Requirement references below are exact links to the complete module text. Each workstream has a single file owner and shared owners for contracts/migrations. W11’s whole-system test ownership does not make it owner of every feature file.')+
 workstreams.map(w=>{const [id,name,dirs,objective,refs,owner,gate]=w;const ms=modules.filter(m=>wsModules[id].includes(m.id));const rs=ms.flatMap(reqs);const api=operations.filter(o=>ms.some(m=>m.code===o.module)||id==='W01'&&o.module==='Foundation'||id==='W10'&&o.module==='Integrations'||id==='W12'&&o.id.includes('Push'));return `<article class="module" id="${id}"><h3>${id} · ${e(name)}</h3><p class="meta">${e(owner)} · ${e(gate)}</p>${table(['Required field','Workstream specification'],[
 ['1. Objective',e(objective)],['2. Exact functional requirements',rs.map(r=>link('#'+r.id,r.id)).join(' · ')+(id==='W01'||id==='W11'?'<br>All INV-01–INV-12 and cross-module FL-01–FL-10.':id==='W02'?'<br>All shared component, state and token contracts in section 11.':'')],['3. Directory / file structure',code(dirs)+'<br>Use the module/controller/service/repository/ports/policies/test file convention in section 15; shared changes require their owner.'],['4. Technologies / dependencies',e(wsTech[id])+'<br>'+ms.map(m=>e(m.dependencies)).join('<br>')],['5. Database responsibilities',id==='W01'?'Own migration registry, global identity/org records, tenant-context functions, composite-key/RLS/grant conventions.':id==='W02'?'No direct database writes; consume shared authorized projections.':id==='W11'?'Own migration execution/role/recovery verification, not domain DML.':ms.map(m=>code(m.entities)).join('<br>')],['6. API / service boundaries',api.length?api.map(o=>link('#api-'+o.id,o.id)).join(' · '):'Consume typed shared API; no module-owned endpoint.'],['7. UI components',ms.map(m=>e(m.ui)).join('<br>')],['8. External integrations',ms.map(m=>e(m.integrations)).join('<br>')],['9. Security / permissions',ms.map(m=>e(m.permissions)).join('<br>')+'<br>INV-01/02/11 apply at API, worker, export and UI boundaries.'],['10. Tests',ms.map(m=>e(m.tests)).join('<br>')+(id==='W11'?'<br>Whole-system FL flows, upgrades, load, restore, security/accessibility and physical-device release matrix.':'')],['11. Acceptance criteria',ms.flatMap(m=>m.acceptance.map((x,i)=>link('#'+m.id+'-AC-'+(i+1),m.id+'-AC-'+(i+1)))).join(' · ')],['12. Definition of done','All linked criteria pass; contracts/generated types and migrations current; relevant scope/concurrency/provider-failure tests pass; responsive/states/accessibility verified; no secrets/live sends; docs/runbooks updated; module/shared owners approve. W11 also proves M8 operational and release gates.']])}</article>`;}).join(''));

 section('operations','17. Operations, scaling, reliability and delivery standards',
 p('Capacity assumptions are planning inputs, not observed reference-platform traffic: initial 500 organizations, 5,000 members, 50 API requests/second with short 5× bursts, up to two million contacts and 100,000 allowed listings per regional feed. Validate/replace this envelope with owner forecasts at M1 and measured representative datasets before sizing production. Do not create those listings from real MLS data in development.')+
 table(['Proposed target','Measurement / operational requirement'],[
 ['Availability','99.9% monthly platform availability within approved launch scope; define maintenance/dependency treatment and error-budget action. Provider outages have visible degraded flows.'],['Workspace API','p95 ≤400ms for ordinary warm reads; public property query p95 ≤800ms at agreed load/filter cases. Separate provider-query latency from platform processing.'],['Web UX','Target p75 LCP ≤2.5s, INP ≤200ms, CLS ≤0.1 on representative mobile connectivity; measure real-user safe telemetry and synthetic runs. These are goals, not audited performance.'],['Bundle budget','Initial authenticated compressed JS target ≤350KB; public non-map page ≤200KB. Lazy-load builders, maps/charts and provider widgets. Record actual measured deltas and revise budget through ADR if base framework cost requires it.'],['Jobs','Define per-purpose latency SLO: ordinary capture notifications within 60 seconds; sending and MLS cadence according to approved policies, not a universal guessed refresh interval. Queue lag alarms precede policy breach.'],['Recovery','Proposed RPO ≤15 minutes, RTO ≤4 hours; managed PITR plus verified restore, object lifecycle and queue recovery. M8 must demonstrate with evidence.'],['Provider budgets','Per-tenant/provider concurrency, request quotas, monthly spend/send/storage caps and circuit breakers. A busy organization cannot starve others.'],['Search / reporting scale','Load-test indexed filters and safe aggregates with EXPLAIN plans; introduce a warehouse/external index only after measured need and privacy/rights review.']])+
 p('Development/staging/production use distinct databases, buckets, identities, domains, queues, secret scopes and provider modes. Preview deployments contain only synthetic identities/listings and no-delivery transports; deny network routes to live feed/send endpoints where practical. Startup validates environment schema and refuses a production live feed with mock/synthetic mode or unresolved policy.')+
 p('CI gates: format/lint → strict types → OpenAPI/event/schema validation and generation drift → unit/UI tests → real PostgreSQL/PostGIS migration/RLS tests → provider mock contracts → relevant E2E and accessibility → image/dependency/secret scan → immutable OCI artifacts with SBOM. Preview checks are reversible; production deployment follows the concrete M8 release decision.')+
 p('Deploy compatible database expansion first, then API/workers/web, monitor canary tenants and drain/advance jobs safely. Feature flags contain new behavior without bypassing entitlements/rights. Roll back images while schema stays compatible; use explicit restore for data incidents. SW update handling cannot force mobile clients into an incompatible contract without a supported API overlap period.')+
 table(['Runbook / monitor','Required evidence'],[
 ['Tenant/security incident','Revoke sessions/grants/device notices, isolate affected provider, preserve safe audit and investigate scope. Named incident owner and escalation path.'],['Billing reconciliation','Current provider subscription read, idempotent projection, failed-provisioning recovery and customer-safe status.'],['MLS freshness/withdrawal','Last run/page/key scan, quota/mapping failures, block stale serving and prove purge propagation.'],['Communication unknown state','Receipt/query/manual reconciliation decision; do not use generic retry for uncertain sends.'],['Queue/cache loss','Recover committed due jobs/outbox, verify dedupe and quotas; Redis is not the sole schedule.'],['Database/object restore','Restore isolated copy, run integrity/RLS checks, reapply deletion/rights revocations, compare job generations and perform approved cutover.'],['PWA release/update','Manifest/icon checks, SW static allowlist, waiting-update behavior, deep-link/session return and physical-device results.'],['Observability','Structured redacted logs, trace IDs, error ratios, queue lag, provider errors, DB pool/locks, cache hit/expiry, costs and scoped health. No raw PII in telemetry by default.']])+
 p('Manage keys through workload identity/secret manager, rotate provider credentials and retain audit references only. Use separate database migration/runtime roles, encrypted storage, private connections and least-privilege object prefixes. Infrastructure is versioned Terraform; owner selects region, sizing and contractual controls. Costs remain a capacity worksheet at M1/M4/M6/M7 rather than fabricated totals.'));

 section('threats','18. Security, privacy and risk controls',
 p('Use OWASP ASVS Level 2 as the initial verification scope and track applicable controls. This is an engineering target, not a certification or completed security audit. Build threat tests alongside modules; do not postpone tenant isolation to M8.'+cite('https://owasp.org/projects/asvs','OWASP ASVS'))+
 table(['Threat / risk','Required mitigation and negative test'],[
 ['IDOR / cross-tenant leaks','Verified membership + own/team/org policy + composite FK/RLS. Test IDs, counts, search, caches, exports, jobs, media and staff grants with A/B organizations and real pooled connections.'],['Privilege escalation / owner race','Delegation intersection, locked last-owner invariant, step-up for sensitive grants, no staff permission through tenant roles. Test concurrent demotions and forged office ownership.'],['Public domain takeover','Exact normalized host ownership, global domain uniqueness, verified TXT/TLS lifecycle, trusted proxy config. Test unknown host, stale ownership and forwarded-host spoofing.'],['XSS / editor content','Registered schemas, sanitized rich text, safe URLs, restrictive CSP with reviewed provider origins, SVG sanitize/reject. No arbitrary tenant executable JS/HTML injection.'],['SSRF / media / push / continuations','Allowlisted origins/protocols, vetted egress and redirect policy, reject localhost/private ranges/DNS rebinding. Never attach MLS credentials to an arbitrary nextLink or user URL.'],['CSV / uploads','Bounded parse/file size, content/MIME sniff, scan/quarantine, tenant object prefix, formula-safe export, explicit dedupe preview. Test spreadsheet formulas and malicious file extensions.'],['Webhook forgery/replay','Exact provider verifier/raw body/canonical URL, timestamp tolerance, connection binding, dedupe event ID and current-state reconciliation.'],['Stale consent / duplicate sends','Current eligibility at dispatch, stable attempt keys, bounded leases/generations, unknown-state reconciliation and explicit unsubscribe/STOP handling.'],['MLS license/address leakage','Fail-closed rights/expiry, sanitization before cache/SEO/map/AI, complete key reconciliation and termination purge. Test metadata, thumbnails and old alert paths.'],['AI prompt injection / data disclosure','Scoped minimal facts, no arbitrary fetch/tools, schema/citation checks, model evaluations, human review and separate draft-only acceptance.'],['Private offline/PWA leaks','No sensitive service-worker/IndexedDB caching, safe generic shell, logout/switch purge and in-memory clearing; test physical device storage after private workflows.'],['Lock-screen privacy','Generic push content, no contact/listing details, authorized click route and revocation/current membership checks.'],['Provider dependency / budget risk','Adapters/mocks/capabilities, timeout/circuit breaker, spend cap and no misleading success. Procurement is a milestone gate.'],['Dependency / recovery defects','Pinned secure versions, SBOM/scans, migration compatibility, PITR/object/queue restore drill and real device update checks.']])+
 p('Privacy choices are owner/jurisdiction decisions at M2/M4/M7: disclosure/consent language, communication and quiet-hour policy, data-subject handling, cookie/analytics purpose, retention/holds and provider processing agreements. This TDD proposes mechanisms and engineering gates; it does not claim a particular policy satisfies all laws. Do not collect protected attributes for scoring or housing eligibility. Preserve only minimal licensed/necessary data.')+
 p('Exports use a durable scoped job and short-lived authorized download gateway. Recheck current membership/role before signing, and avoid direct forever-public object URLs. Import commits and contact merges audit review choices. Consent withdrawals append evidence and suppress future sends; deleting a contact does not erase necessary suppression into renewed eligibility.'));

 section('roadmap','19. Milestones, prerequisites and dependency sequencing',
 p('Sequence is driven by contracts and complete flows. Establish MLS/PWA seams during foundation; the property mock UI can advance alongside marketing once CRM capture and public sites are stable. AI/reporting without live listing data does not wait for live Trestle credentials. M6 gates live IDX rather than unrelated development.')+
 milestones.map(m=>`<article class="module" id="${m[0]}"><h3>${e(m[0]+' · '+m[1])}</h3>${table(['Field','Milestone definition'],[['Prerequisites',e(m[2])],['Deliverables',e(m[3])],['Acceptance / exit gate',e(m[4])],['Owners',e(m[5])],['Risks / constraints',e(m[6])],['Mobile/PWA gate',e(m[0]==='M1'?'Manifest/SW cache policy, original icon specifications and device workflow contract frozen.':m[0]==='M8'?'Physical iPhone/Android browser and installed acceptance, update/offline/push/privacy checks pass.':'All delivered module commands work on iPhone/Android responsive browser and standalone layouts; no desktop-only critical path.')]])}</article>`).join('')+
 table(['Parallel wave','Workstreams / dependency'],[
 ['Wave 1 · M1','W01 contracts/tenancy; W02 tokens/shell; W11 environments/CI; W07 MLS ports; W12 PWA seams. Shared contract review precedes competing consumer edits.'],['Wave 2 · M2','W03 SaaS/dashboard/support and W04 CRM, W08 metric/event basics, W12 mobile parity; real isolation and capture flow integrate before CMS.'],['Wave 3 · M3','W05 CMS/public sites with W02/W12 device editor patterns; W04 shared capture support.'],['Wave 4 · M4/M5','W06 marketing and W07 mock IDX in parallel; W10 selected provider operations; W08 receipt/property metric definitions. Alerts integrate through frozen ports.'],['Wave 5 · M6/M7','Authorized Trestle adapter after owner inputs; W08 reporting, W09 non-MLS AI and W10 local capabilities progress independently where prerequisites permit.'],['Wave 6 · M8','W11 whole-system QA/restore/load/security; W12 physical devices; each owner resolves release defects and proves linked acceptance.']])+
 p('No fixed completion date or headcount estimate is claimed without team availability and provider lead times. Track milestone acceptance evidence rather than an invented calendar. A CRM/CMS-only release may proceed if explicitly scoped and M8-ready; a release advertised as live Las Vegas IDX requires M6 compliance and provider acceptance. The owner’s full mobile-web requirement remains part of every release scope.'));

 section('verification','20. Verification, decisions and implementation handoff',
 table(['Test layer','Meaningful required coverage'],[
 ['Unit / UI','Rule graph, scope/delegation, last-owner transition logic, deterministic routing/scoring, merge/consent, block migration, metric definitions, schema validation, install/cache/update policy. Avoid tests that merely mirror implementation.'],['Database integration','Actual PostgreSQL/PostGIS, composite FK errors, RLS grants, missing context, actor bootstrap, A/B tenant pool reuse, owned/team aggregates, last-owner races and empty/upgrade migrations.'],['Jobs / providers','Crash before/after commit/acceptance, duplicate/out-of-order webhooks, 429, token expiry, Redis loss, lease generation cancellation, reconciliation and signed callback errors.'],['MLS contract suite','Fictional lifecycle/filter/spatial/media/status/policy/timestamp/cursor fixtures; partial reconciliation does not delete; mock/live separation. M6 approved Trestle source comparisons and attribution/freshness/withdrawal tests.'],['Integrated browser E2E','FL-01–FL-10 across scopes and degraded states; responsive editor alternatives, visit/session boundaries, export reauthorization and billing sandbox.'],['Mobile/PWA physical','iPhone Safari and home-screen app; Android Chrome and installed app; login/return, keyboard/safe area, all core commands, offline/idempotent reconnect, push denial/revocation and safe SW upgrade.'],['Accessibility','Automated axe plus keyboard, VoiceOver/TalkBack, zoom/reflow, focus dialogs, error summaries, charts/maps/list alternatives, accessible authentication and embedded editor coverage.'],['Load / recovery / security','Representative synthetic capacity; query plans, tenant fairness and provider-budget limits; private cache/SSRF/IDOR checks; PITR/object/queue restore and rollback drill.'],['AI evaluation','Versioned synthetic/redacted datasets, quality/factuality/safety/cost/latency rubric and acceptance-only-as-draft tests before production enablement.']])+
 table(['Decision / assumption','Owner and timing'],[
 ['Brand, plan prices/limits and launch scope','Owner/product · M1–M2; token/catalog defaults are proposals.'],['Hosting region/capacity and identity tenant','Owner + W11/W01 · M1; secure compatible runtime pins and actual sizing.'],['Communication/privacy/retention rules','Owner + relevant reviewers · M2/M4/M7; mechanisms do not establish legal sufficiency.'],['Editor, tile, email/SMS/local licensing','W05/W06/W07/W10 + owner · relevant milestone; selected ports support replacement.'],['Trestle provider choice','Confirmed by owner during drafting. Actual approved Las Vegas feed product/access/display rules remain M6.'],['iPhone/Android app distribution','Confirmed owner requirement: full web app plus home-screen PWA; no app stores. W12/W02/W11 acceptance required.'],['Provider costs/model selection','Owner + W09/W11 · M7; evaluate current approved configuration.'],['Runtime readiness','All module owners + W11 · M8; requires actual tests and operational evidence, not document generation.']])+
 p('Start implementation with M1: approve/freeze the contract baseline, create the future repository, apply AGENTS.md, verify current dependency pins, implement transaction context/roles, establish CI and mock provider ports, and prove tenant isolation. Next deliver M2 capture→assignment→task and native SaaS flows on desktop/iPhone/Android. Do not start by requesting live MLS credentials.')+
 callout('Artifact validation covers generated-file consistency, schema references, feature/module/workstream traceability, links and the readable report. It does not execute the database schema, test application endpoints, connect Trestle, verify contractual compliance or prove physical-device functionality. Those remain explicit implementation gates.')+
 p('Companion '+link('validation.json','validation.json')+' records checks and limitations; '+link('manifest.json','manifest.json')+' records file hashes. Builder source is included for reproducibility. Official documentation links appear beside the design claims they support; the original audit bundle preserves observed evidence and its limitations.'));
 const workstreamSpecs=workstreams.map(w=>{const ms=modules.filter(m=>wsModules[w[0]].includes(m.id));return {id:w[0],name:w[1],owner:w[5],milestones:w[6],objective:w[3],functionalRequirementIds:ms.flatMap(m=>reqs(m).map(r=>r.id)),directories:w[2].split('; '),technologies:wsTech[w[0]],dependencies:ms.map(m=>m.dependencies),databaseResponsibilities:ms.map(m=>m.entities),apiOperationIds:operations.filter(o=>ms.some(m=>m.code===o.module)||w[0]==='W01'&&o.module==='Foundation'||w[0]==='W10'&&o.module==='Integrations'||w[0]==='W12'&&o.id.includes('Push')).map(o=>o.id),ui:ms.map(m=>m.ui),integrations:ms.map(m=>m.integrations),securityPermissions:ms.map(m=>m.permissions),tests:ms.map(m=>m.tests),acceptanceIds:ms.flatMap(m=>m.acceptance.map((x,i)=>m.id+'-AC-'+(i+1))),definitionOfDone:'All linked acceptance, relevant scope/concurrency/provider tests, contract generation, migrations, mobile/accessibility, docs/runbooks and shared-owner approvals; M8 additionally for production release.'};});
 const document={version:'1.0.0',date:'2026-10-10',status:'Proposed architecture; no application deployed',ownerRequirements:{mlsProvider:'CoreLogic/Cotality Trestle',authorizedConnection:'M6 owner-provided access and approved Las Vegas feed rights; not yet verified',application:'Full web application; installable iPhone and Android PWA; no app stores'},contractStats,supplementStats,invariants,adrs,comparison,modules:modules.map(m=>({...m,requirements:reqs(m)})),workstreams:workstreamSpecs,milestones:milestones.map(m=>({id:m[0],name:m[1],prerequisites:m[2],deliverables:m[3],exitGate:m[4],owners:m[5],risks:m[6]})),tokens,contrastPairs,sections};
 const html=renderHtml(sections,contractStats);
 await fs.writeFile(path.join(out,'real-estate-saas-tdd-2026-10-10.html'),html);
 await fs.writeFile(path.join(out,'technical-design.json'),JSON.stringify(document,null,2));
 await fs.writeFile(path.join(out,'READ-ME.txt'),`COMPETITIVE REAL ESTATE SAAS — TDD 1.0\n10 October 2026\n\nOpen real-estate-saas-tdd-2026-10-10.html in a browser. Keep companion folders beside it.\n\nThis is a design blueprint, not an implemented or deployed application.\nOwner-selected MLS provider: CoreLogic/Cotality Trestle. Authorized Las Vegas account/feed rights and credentials remain M6 inputs. No live feed was connected.\nOwner requirement: complete web application and home-screen PWA on iPhone and Android, without app-store distribution. Real-device acceptance is M8.\n\nFILES\n- technical-design.json: structured design, modules, requirements, workstreams, milestones and section content.\n- contracts/openapi.json: proposed OpenAPI 3.1.1 contract.\n- contracts/mls-adapter.ts: type-only provider interface; no actual adapter implementation.\n- contracts/events.schema.json and permission-catalog.json: shared boundary contracts.\n- contracts/pwa-manifest.example.json and pwa-policy.json: manifest/cache/update design; icons/service worker not implemented.\n- data/schema.sql, data-dictionary.json, schema.mmd: proposed PostgreSQL/PostGIS model. SQL not applied.\n- design-system: original shared tokens.\n- fixtures/synthetic-listings.json: 12 entirely fictional records, fixed test clock, not MLS data.\n- future-repo/AGENTS.md: future implementation rules; not installed as this workspace's root instructions.\n- reference/source-audit.json: entire previous audit.\n- reference/Agent-Elite-Audit-2026-10-10.zip: original audit report and evidence; extract separately to inspect evidence paths.\n- diagrams: original architecture, relationships, MLS and workspace design SVGs.\n- validation.json, manifest.json: artifact checks and SHA-256 inventory.\n\nREPRODUCIBILITY\nBuilder source is under source/. With a compatible Node.js runtime, run node source/build.mjs from the extracted folder. It needs no third-party packages, no credentials and no provider calls. It rebuilds design artifacts only. ZIP packaging/physical browser preview are separate delivery checks.\n\nVALIDATION LIMITS\nStructural checks do not substitute for PostgreSQL migrations, API tests, physical-device functionality, provider licensing or M8 operational readiness. Read the TDD gates before implementation.\n`);
 return {sections:sections.length,contractStats,supplementStats,modules:modules.length,workstreams:workstreams.length,features:comparison.length,htmlBytes:Buffer.byteLength(html)};
}

function renderHtml(sections,stats){return `<!doctype html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width, initial-scale=1"/><title>Competitive Real Estate SaaS — Technical Design Document</title><style>
:root{font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif;color:#172238;background:#F5F7FB;font-size:16px;line-height:1.6;--nav:#15263F;--blue:#2459B8}*{box-sizing:border-box}body{margin:0;overflow-x:clip}a{color:var(--blue);text-underline-offset:3px}a:hover{color:#19458F}a:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid var(--blue);outline-offset:4px}.skip{position:fixed;top:-100px;left:16px;padding:12px;background:white;z-index:9}.skip:focus{top:12px}.masthead{background:var(--nav);color:white;padding:48px max(28px,calc((100vw - 1260px)/2));border-bottom:5px solid #43BAA0}.masthead .eyebrow{color:#A9C8EB;letter-spacing:.14em;font-size:12px;font-weight:700}.masthead h1{font-size:clamp(30px,4vw,46px);line-height:1.18;max-width:900px;margin:16px 0}.masthead p{max-width:860px;color:#D3DFF1}.masthead a{color:#D3E4FF}.stats{display:flex;gap:12px;flex-wrap:wrap;margin-top:24px}.stats span{border:1px solid #537094;border-radius:8px;padding:8px 14px}.layout{max-width:1320px;margin:auto;display:grid;grid-template-columns:244px minmax(0,1fr);gap:32px;padding:32px 28px}nav{position:sticky;top:16px;height:calc(100vh - 32px);overflow:auto;font-size:13px}nav h2{font-size:14px;text-transform:uppercase;letter-spacing:.08em}nav a{display:block;padding:8px 9px;color:#52617A;text-decoration:none;border-left:2px solid #CBD3DF}nav a:hover{background:#E9EEF8;color:#172238}main{min-width:0}section{background:white;padding:32px;border:1px solid #CBD3DF;border-radius:12px;margin-bottom:24px;scroll-margin-top:20px}h2{font-size:26px;line-height:1.3;margin:0 0 22px;padding-bottom:14px;border-bottom:2px solid #E9EEF8}h3{font-size:21px;line-height:1.4;margin:28px 0 12px}h4{font-size:16px;margin:24px 0 10px}p{margin:12px 0 18px}li{margin-bottom:10px}.meta,small,.citation,figcaption{font-size:12px;color:#52617A}.citation{white-space:normal}.citation a{font-weight:500}.callout{background:#E9F1FC;border-left:4px solid #2459B8;border-radius:5px;padding:16px 20px;margin:18px 0 24px}.table-wrap{width:100%;margin:20px 0;overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px;line-height:1.55;table-layout:fixed}th{text-align:left;background:#E9EEF8;padding:12px 10px;font-weight:700;border-bottom:2px solid #CBD3DF}td{vertical-align:top;border-bottom:1px solid #DDE3ED;padding:12px 10px;overflow-wrap:anywhere}tr:nth-child(even)td{background:#FAFBFD}table th:first-child{width:24%}table.feature-matrix th:first-child{width:21%}table.feature-matrix th:nth-child(2){width:32%}table.feature-matrix th:nth-child(3){width:34%}table.feature-matrix th:last-child{width:13%}code{font-family:ui-monospace,Consolas,monospace;font-size:.91em;background:#F0F3F8;padding:1px 4px;border-radius:3px;overflow-wrap:anywhere}pre{background:#15263F;color:#E8EFF9;padding:20px;border-radius:8px;white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.7}.badge{display:inline-block;font-size:11px;font-weight:700;background:#E9EEF8;border:1px solid #CBD3DF;padding:2px 6px;border-radius:5px;margin:0 0 6px}figure{margin:22px 0}figure img{width:100%;height:auto;display:block;border:1px solid #CBD3DF;border-radius:10px}figcaption{margin-top:8px}.module{padding:12px 0 22px;margin:8px 0 20px;border-bottom:1px solid #CBD3DF}.module h3{color:#19458F}.requirements li{padding-left:4px}.requirements strong{font-size:12px;color:#2459B8}details{border:1px solid #CBD3DF;border-radius:8px;padding:12px 16px;margin:12px 0}summary{cursor:pointer;font-weight:600;overflow-wrap:anywhere}details>summary .meta{margin-left:8px}input[type=search]{display:block;margin-top:7px;font:inherit;padding:12px 14px;width:100%;border:1px solid #CBD3DF;border-radius:8px}.filter-label{font-size:14px;font-weight:600}footer{padding:24px 28px 48px;text-align:center;color:#52617A;font-size:12px}
@media(max-width:1000px){.layout{grid-template-columns:1fr}nav{position:static;height:auto;columns:2;font-size:13px;padding:16px;background:white;border:1px solid #CBD3DF;border-radius:10px}nav h2{column-span:all}nav a{break-inside:avoid}section{padding:24px}}@media(max-width:600px){.layout{overflow-x:clip}main,section,.module,details,.table-wrap{max-width:100%;min-width:0}.masthead{padding:30px 20px}.layout{padding:20px 12px;gap:20px}nav{columns:1}section{padding:18px 14px}h2{font-size:23px}table{min-width:620px}figure{overflow:auto}figure img{min-width:650px}pre{padding:14px}.stats span{font-size:13px}}@media print{body{background:white}.masthead{padding:20px;color:#172238;background:white;border-color:#CBD3DF}.masthead p,.masthead .eyebrow{color:#52617A}.masthead a{color:#2459B8}.layout{display:block;padding:0;max-width:none}nav,.filter-label,#filter-count{display:none}section{border:0;border-radius:0;padding:20px 0;break-before:page}section:first-child{break-before:auto}details{border:0;padding:0}details>summary{margin:20px 0}table{font-size:10px}tr{break-inside:avoid}figure img{min-width:0}h2,h3,h4{break-after:avoid}pre{background:#F0F3F8;color:#172238}.table-wrap{overflow:visible}}
</style></head><body><a class="skip" href="#content">Skip to document</a><header class="masthead"><div class="eyebrow">INDEPENDENT PLATFORM · TECHNICAL DESIGN DOCUMENT · V1.0</div><h1>Competitive Real Estate SaaS<br>Architecture &amp; Development Blueprint</h1><p>A complete implementation specification for tenant administration, native CRM, premium websites, marketing, Trestle-ready IDX and assistive AI — delivered as a full web application and installable iPhone/Android PWA without app stores.</p><p>10 October 2026 · Proposed design · Source audit preserved · Live MLS authorization at M6</p><div class="stats"><span>${tables.length} entities</span><span>${operations.length} API operations</span><span>${modules.length} modules</span><span>${workstreams.length} workstreams</span><span>8 milestone gates</span></div><p>${link('technical-design.json','Structured TDD')} · ${link('contracts/openapi.json','OpenAPI')} · ${link('future-repo/AGENTS.md','Codex repository rules')}</p></header><div class="layout"><nav aria-label="Document contents"><h2>Document contents</h2>${sections.map(s=>link('#'+s.id,s.title)).join('')}</nav><main id="content">${sections.map(s=>`<section id="${s.id}"><h2>${e(s.title)}</h2>${s.html}</section>`).join('')}</main></div><footer>Independent proposed architecture · No application deployment, live provider access or production-readiness claim · Original evidence and artifact validation included</footer><script>const input=document.getElementById('feature-filter');const rows=[...document.querySelectorAll('.feature-matrix tbody tr')];input.addEventListener('input',()=>{const q=input.value.trim().toLowerCase();let n=0;for(const row of rows){row.hidden=!row.textContent.toLowerCase().includes(q);if(!row.hidden)n++;}document.getElementById('filter-count').textContent=n+' of '+rows.length+' audit features';});window.addEventListener('beforeprint',()=>{for(const d of document.querySelectorAll('details'))d.open=true;});</script></body></html>`;}
